programs.sol:
"""A small lexical approximation to a settings-and-collectives feature.

Training responses are strongest for courts and households, and weaker for
families, markets, shared spaces, communities, and surrounding systems.
The rules recognize listed words (with simple plural handling) and several
Chinese/Japanese equivalents. They ignore context and leave unlisted tokens
at zero; this is not a complete semantic classifier.
"""

READS = ()

FAMILY = {'family'}
MARKETS = {'market', 'marketplace'}
ACTIVITY_SPACES = {'kitchen', 'classroom', 'battlefield', 'circuit'}
SCENES = {'scene'}
COMMUNITIES = {'society', 'community'}
INSTITUTIONS = {'senate', 'parliament', 'congress', 'government', 'committee',
                'church', 'audience', 'jury', 'commonwealth'}
SETTLEMENTS = {'county', 'town', 'village', 'neighborhood', 'neighbourhood',
               'campus', 'hospital', 'street', 'township', 'stadium', 'farm'}
SYSTEMS = {'system', 'culture', 'industry', 'economy', 'media', 'ecosystem'}
SITUATIONS = {'situation', 'scenario', 'circumstance'}
SPACES = {'field', 'plot', 'landscape', 'forest', 'room', 'laboratory', 'garden'}
AGGREGATES = {'group', 'team', 'population', 'network', 'panel', 'column',
              'department', 'layer'}
ENVIRONMENTS = {'country', 'city', 'house', 'ground', 'surface', 'environment',
                'district', 'context', 'site', 'chamber'}
BIOLOGICAL = {'cell', 'cellular', 'tissue', 'skin', 'muscle', 'gut', 'plasma',
              'immune'}
LEGAL_CASES = {'case', 'trial', 'judicial'}

WORD_CLASSES = (
    (FAMILY, 1.4), (MARKETS, 2.0), (ACTIVITY_SPACES, 1.8), (SCENES, 1.3),
    (COMMUNITIES, 1.1), (INSTITUTIONS, 0.9), (SETTLEMENTS, 0.7),
    (SYSTEMS, 0.75), (SITUATIONS, 0.85), (SPACES, 0.75),
    (AGGREGATES, 0.48), (ENVIRONMENTS, 0.4), (BIOLOGICAL, 0.48),
    (LEGAL_CASES, 0.52),
)

# Chinese/Japanese glossary: communal interiors, groups, places, and systems.
COMMUNAL_SPACES = {'影院', '教室', '客厅', '厨房', '堂', '厅', '廟', '家里',
                      '校园', '舞台'}
GROUP_IDEOGRAPHS = {'社区', '社', '团', '团队', '家族', '家长', '户'}
PLACE_IDEOGRAPHS = {'村', '田', '野', '院', '台', '街', '乡', '市', '土', '林',
                    '地区', '小区', '实验室', '景区', '领域', '領域', '园', '園'}
SYSTEM_IDEOGRAPHS = {'系统', '政府', '情况', '況', '室', '医院', '行业'}


def singular(word):
    if word.endswith('ies'):
        return word[:-3] + 'y'
    if word.endswith('ches'):
        return word[:-2]
    if word.endswith('s') and not word.endswith(('ss', 'us')):
        return word[:-1]
    return word


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().strip('.,;:/_-()[]{}').lower()
    word = singular(token)
    value = 0.0
    for words, strength in WORD_CLASSES:
        if word in words:
            value = strength
            break
    if word in {'court', 'courtroom'}:
        value = 3.7 if token == 'courts' else 4.4
        if not raw[:1].isspace():
            value = 3.0
        if raw.strip()[:1].isupper():
            value = 3.4
    elif word == 'household':
        value = 4.0
    elif word == 'family' and not raw[:1].isspace():
        value = 0.8
    elif word in {'soil', 'clinical'}:
        value = 1.25
    elif word in {'social', 'local', 'urban', 'rural'}:
        value = 0.65
    elif token == 'situations':
        value = 1.5
    elif token == 'tissues':
        value = 1.15
    elif token == 'patients':
        value = 0.33

    # 庭 denotes a court/courtyard, or the household in 家庭 (family).
    if '庭' in token:
        value = 5.3
        if token == '庭':
            value = 6.0
        elif token.startswith('庭'):
            value = 4.2
    elif token in {'法院', '人民法院', '宫廷', '朝廷'}:
        value = 3.2
    # 场/場 denotes a field or setting; 市场/市場 means market.
    elif '场' in token or '場' in token:
        value = 1.5
        if '市场' in token or '市場' in token or token in {'现场', '現場', '战场'}:
            value = 2.3
        if '場合' in token:  # Japanese "case/circumstance"
            value = 0.65
    elif token.endswith(('社会', '社會')):  # society
        value = 1.8
    elif token in COMMUNAL_SPACES:
        value = 1.6
    elif token in GROUP_IDEOGRAPHS:
        value = 1.1
    elif token in PLACE_IDEOGRAPHS:
        value = 0.95
    elif token in SYSTEM_IDEOGRAPHS:
        value = 0.8
    elif token in {'组', '群', '体系', '县', '城市', '房', '公园', '屋顶', '网络'}:
        value = 0.6
    return None, float(value)

programs.luna:
"""Approximate a rare line-structure feature.

Positive guesses mark indentation or a few visible list/comment leaders at
line beginnings. Ordinary text away from these structural starts predicts 0.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        at_line_start = True
    else:
        at_line_start = carry[1]

    # A token can itself contain a line break followed by indentation.
    if "\n" in token:
        line_part = token.rsplit("\n", 1)[-1]
        token_starts_line = not line_part.strip(" \t")
        visible = line_part.lstrip(" \t")
    else:
        token_starts_line = at_line_start
        visible = token.lstrip(" \t")

    value = 0.0
    if token_starts_line:
        if not visible:
            # Indentation is a weak cue; it is common in source and prose.
            if token.strip(" \t\n") == "" and token.strip("\n"):
                value = 0.32
        elif visible.startswith("//"):
            value = 1.45
        elif visible.startswith("#"):
            value = 0.95 if not visible.startswith("###") else 0.48
        elif visible.startswith("*"):
            value = 0.48
        elif visible.startswith(("-", "•")):
            value = 0.55

    # Carry whether the next token is still at the start of its line.
    if "\n" in token:
        tail = token.rsplit("\n", 1)[-1]
        next_line_start = not tail.strip(" \t")
    elif token.strip(" \t"):
        next_line_start = False
    else:
        next_line_start = at_line_start
    return (doc, next_line_start), float(value)

"""A weak surface-form proxy for rare positive lexical responses.

A longer, capitalized, identifier-like, or non-Latin word gets a small
positive estimate; ordinary and non-word tokens get little or none.
"""
import unicodedata

READS = ()
TECHNICAL_ENDINGS = (
    "tion", "sion", "ment", "ness", "ity", "ism", "ics", "ist",
    "ology", "ware", "code", "map", "list",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = "".join(ch for ch in token if ch.isalpha())
    if not word:
        return None, 0.0

    value = 0.006 if len(word) >= 4 else 0.0
    if len(word) >= 8:
        value += 0.025
    if len(word) >= 12:
        value += 0.035
    if word.lower().endswith(TECHNICAL_ENDINGS):
        value += 0.025
    if word[0].isupper() or any(ch.isupper() for ch in word[1:]):
        value += 0.07
    if any("LATIN" not in unicodedata.name(ch, "") for ch in word):
        value += 0.06
    if any(ch in token for ch in "_.@") and len(word) >= 3:
        value += 0.04
    return None, value * 0.125

programs.sol:
"""Negative activation for motion, dynamic/static states and activity vocabulary.

This is a small, graded lexicon rather than a general meaning classifier.
Motion ideographs are particularly strong; their compounds are weaker.
The effect sometimes continues onto 'of' or an article after a motion word.
Document boundaries reset this one-token memory. Other tokens predict zero.
"""
READS = ()

# Strength tiers: related words and ordinary morphological fragments.
TIERS = (
    (3.8, 'dynamic ynamic'),
    (3.2, 'motion'),
    (2.3, 'move moves moved moving movement movements motions movable'),
    (2.1, 'dynamics dynam ynam automated animated'),
    (2.6, 'automatic dynamically'),
    (1.8, 'motor interactive static automate automatically'),
    (1.4, 'animal animals animation animations animate automation autom automat '
          'kinetic kinetics brake braking vibration robotics staticmethod'),
    (1.0, 'action actions activity activities mobile dyn mov mobil motive '
          'motivation robot robots robotic quiet fluctuations oscill gesture '
          'maneuver motivated motives statically otor otion'),
    (0.65, 'drive drives driven driving driver drivers interaction interactions '
          'interact behavior behaviour mechanical mechanism mechanisms active '
          'activate activated activation actively auto automotive rotation '
          'rotating mobility noise fluid manual manually innovative dance '
          'dancing rolling sliding stirring emotion emotions emotional'),
)
LEXICON = {word: strength for strength, words in TIERS for word in words.split()}


def strength(s, previous):
    if s in ('动', '動'):
        root = previous[-1:]
        if root and root in '移自':
            return 3.8
        if root and root in '振變変啟启起勞劳扰擾涌煽':
            return 4.8
        if root and root in '扭滑轰拖气反暴摆扇鼓帶滾':
            return 6.2
        if '\ufffd' in previous:
            return 4.4
        return 8.1 if s == '动' else 7.3
    if '动' in s or '動' in s:
        if s in ('不动', '不動'):
            return 5.1
        if s in ('动态', '動態'):
            return 4.6
        if s in ('动作', '動作', '动静', '動靜'):
            return 3.6
        if s in ('动漫', '動漫'):
            return 0.7
        return 2.8 if len(s) <= 2 else 2.1
    if s == '동':
        return 4.2
    if s in ('静', '靜', '静态', '靜態', '働'):
        return 2.1
    if s in ('推进', '推進', '创新', '創新', '变化', '變化', '行为', '行為', '舞'):
        return 1.0
    word = s.strip('._-/()').lower()
    value = LEXICON.get(word, 0.0)
    if value:
        return value
    if word.endswith(('odynamic', 'odynamics')):
        return 1.8
    if s.endswith('Move') and not word.endswith('remove'):
        return 2.2
    if word in ('движ', 'двиг', 'động', 'ركة', 'حركة'):
        return 2.7
    if word in ('автомат', 'живот', 'движения', 'movimiento', 'movimientos'):
        return 1.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, prior = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, prior = carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    if '\ufffd' in s and previous:
        text = prefix.text_prefixes[-1]
        if text and text[-1] in '动動동':
            s = text[-1]
    value = strength(s, previous)
    if value and token == token.lstrip() and s.isascii() and s[:1].islower():
        value *= 0.85
    if not value:
        if s == 'of':
            return (doc, s, 0.0), -0.45 * prior
        if previous.lower() in ('move', 'moved', 'moving', 'moves'):
            if s in ('the', 'a'):
                return (doc, s, 0.0), -0.6 if s == 'the' else -0.25
    return (doc, s, value), -float(value)

programs.luna:
"""Approximate a rare negative feature for movement and activity words.

It looks only at the current token: Chinese motion characters and English
movement terms get larger negative estimates; action and mechanism words get
smaller ones. Other tokens are predicted as zero.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if "动" in word or "動" in word:
        value = -4.1
    elif word.startswith(("dynam",)):
        value = -3.5
    elif word.startswith("motion"):
        value = -2.9
    elif word.startswith("mov") and not word.startswith("movie"):
        value = -2.1
    elif word.startswith("automat"):
        value = -2.0
    elif word.startswith("acti"):
        value = -0.46
    elif word.startswith(("operat", "mechan", "behav", "drive", "auto")):
        value = -0.5
    else:
        value = 0.0

    return None, float(value)

programs.sol:
"""A lexical detector of accompaniment and means, especially token 'with'.

'With' in title case is strongest. For ordinary lowercase 'with', common
preceding collocations attenuate the negative response. Fallbacks use
pronouns, word endings, and punctuation. 'By' has smaller phrase/ending
rules. Translations and spelling relatives have weaker fixed responses;
all other tokens get zero. Only an 80-character text tail is remembered,
reset at document boundaries. This is not a full semantic parser.
"""
import re

READS = ()

# Common complements of 'with', from stronger to weaker attenuation.
COLLOCATIONS = (
    (-0.4, 'associated familiar synonymous'),
    (-1.1, 'compared consistent inconsistent comply aligned compatible '
           'incompatible concerned acquainted'),
    (-1.5, 'dealing filled contact affiliated connected compliance'),
    (-1.9, 'along correlated correlate deal dealt association replaced '
           'interfere comparison accordance interact agrees related'),
    (-2.3, 'equipped conjunction agree loaded love covered connect diagnosed '
           'connection starting interaction relationship'),
    (-2.8, 'combined together mixed fitted provided matches match agreement '
           'wrong involved'),
    (-3.1, 'start started begin working worked treated help up do line '
           'problems border issue issues communicate'),
)
COLLOCATIONS = tuple((value, frozenset(words.split()))
                     for value, words in COLLOCATIONS)

# Translations of 'with', 'without', and markers of using something.
MEANS_WORDS = {
    'avec': -2.6, 'con': -2.3, 'com': -1.6, 'mit': -1.6,
    'с': -0.66, 'với': -1.8, 'dengan': -1.8, 'مع': -1.0,
    '以': -1.0, '用': -0.5, '使用': -0.5,
    '与': -0.4, '與': -0.4, '带': -0.4, '帶': -0.4,
    'без': -0.65, 'ohne': -0.65, 'via': -0.65, 'through': -0.35,
}


def activation(token, tail):
    word = token.strip(' \t\n\r-_.()[]{}"\'`—')
    lower = word.lower()
    previous = ''
    if lower in ('with', 'by'):
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        previous = match.group(1).lower() if match else ''
    if lower == 'with':
        if word == 'WITH':
            return -4.05 if token.startswith(' ') else -5.3
        if word == 'With':
            return -5.9 if token.startswith(' ') else -6.3
        if not token.startswith(' '):
            return -5.9 if token[:1] in '.(-' else -4.8
        for value, words in COLLOCATIONS:
            if previous in words:
                return value
        if previous == 'finished':
            return -5.4
        if previous in ('completed', 'called', 'and', 'or', 'but', 'even'):
            return -4.9
        if previous in ('you', 'me', 'them', 'him', 'us', 'each',
                        'myself', 'yourself', 'themselves'):
            return -3.15
        if previous.endswith(('ed', 'ing')):
            return -3.65
        if re.search(r'[.!?:]\s*$', tail):
            return -5.7
        if re.search(r'[,;(]\s*$', tail):
            return -5.0
        return -4.15
    if lower in ('within', 'without'):
        return -1.3 if word[:1].isupper() else -1.0
    if lower == 'width':
        return -0.9 if token.startswith('-') else -1.3
    if lower == 'ith':
        return -1.2
    if lower == 'by':
        if word == 'By':
            return -0.78
        if previous in ('followed', 'accompanied', 'supported'):
            return -1.3
        if previous == 'step':
            return -0.1
        if previous.endswith(('ed', 'en')) or previous in ('made', 'shown'):
            return -0.72
        return -0.46
    if lower == 'с' and token != ' с':
        return -0.1
    if lower in ('con', 'com', 'mit') and token != ' ' + lower:
        return -0.5 if lower == 'com' else -0.7
    return MEANS_WORDS.get(lower, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, tail)
    return (doc, (tail + token)[-80:]), value

programs.luna:
"""A strong negative response to 'with', larger at sentence starts or after
punctuation, with smaller responses to related prepositions and translations.
"""
READS = ()

WITH_TRANSLATIONS = {
    "con": -2.3,   # Romance-language "with"
    "mit": -1.65,  # German
    "avec": -2.7,  # French
    "com": -1.45,  # Portuguese
    "с": -0.7,     # Russian
}

OTHER_PREPOSITIONS = {
    "by": -0.7,
    "within": -1.0,
    "without": -1.05,
    "via": -0.6,
    "through": -0.37,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(" \t\r\n,.;:!?()[]{}<>\"'`_")
    lower = word.casefold()

    if lower == "with":
        if word[:1].isupper():
            return None, -6.0
        if token.startswith(" "):
            if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
                previous = prefix.token_strings[-2].strip()
                if previous and all(not ch.isalnum() for ch in previous):
                    return None, -5.0
            return None, -3.8
        return None, -5.1

    starts_word = token.startswith(" ") or word[:1].isupper()
    if starts_word and lower in WITH_TRANSLATIONS:
        value = WITH_TRANSLATIONS[lower]
        if word[:1].isupper():
            value *= 0.4
        return None, value
    if starts_word and lower in OTHER_PREPOSITIONS:
        return None, OTHER_PREPOSITIONS[lower]
    return None, 0.0

programs.sol:
"""A full-stop and punctuation response, not a general word detector.
Standalone periods after prose and the East Asian full stop are strongest.
Dots after numbers, initials, abbreviations and code-like separators are weaker;
line breaks and attached brackets or quotes change the punctuation baseline.
A small context correction uses sentence length, letter case, numerical/code
content and document position, with coefficients fitted on training rows.
Context consists of a 240-character window, the previous token and document
position, and resets at document boundaries. Other tokens stay near zero.
"""
import math
import re

READS = ()
ABBREVIATIONS = frozenset('''mr mrs ms dr prof st jr sr no nos fig figs eq eqs
al etc vs cf inc ltd co corp vol pp pg p ch sec art gen col dept univ approx
ref refs resp ed eds rev hon fr ave blvd assoc soc sub sup e.g i.e'''.split())


def base_level(token, before):
    s = token.strip()
    n = token.count('\n')
    if token.startswith('<|') or token.startswith('</tool'):
        return (-0.033, 'fixed')
    if '，' in token:
        return (0.62, 'punctuation')
    if s in ('、', '；', '،', '：'):
        return (0.413, 'punctuation')
    if '。' in s and not any(c.isalnum() for c in s):
        if n:
            return (0.78, 'punctuation')
        return (1.695, 'punctuation') if s != '。' else (3.133, 'punctuation')
    if s in ('！', '？'):
        return (1.065, 'punctuation') if s == '？' else (1.452, 'punctuation')
    if '.' in s and not any(c.isalnum() for c in s):
        if s.count('.') > 1:
            return (-0.054, 'punctuation')
        if s.endswith(',') or s.endswith(';') or '/' in s:
            return (0.044, 'punctuation')
        if n:
            if s == '.':
                return (0.519, 'punctuation') if n == 1 else (0.478, 'punctuation')
            return (0.28, 'punctuation')
        if s == '.':
            if token.startswith(' '):
                return (0.834, 'punctuation')
            m = re.search(r'(\w+)$', before)
            word = m[1] if m else ''
            if word and word[-1].isdigit():
                return (1.206, 'punctuation')
            if len(word) == 1:
                return (0.81, 'punctuation')
            if word.lower() in ABBREVIATIONS:
                return (0.675, 'punctuation')
            if word and all(c in 'IVXLCDM' for c in word):
                return (1.002, 'punctuation')
            if m and m.start() and before[m.start()-1] in './_\\':
                return (1.302, 'punctuation')
            return (1.521, 'prose')
        if s.endswith('.'):
            if ')' in s or ']' in s or '}' in s:
                return (1.307, 'punctuation')
            return (1.534, 'punctuation')
        if s.startswith('.'):
            if '"' in s or '”' in s or "'" in s or '’' in s:
                return (0.749, 'punctuation')
            return (0.265, 'punctuation')
    if s in ('!', '?', '！', '？'):
        if n:
            return (0.026, 'punctuation') if n == 1 else (0.183, 'punctuation')
        return (0.846, 'punctuation') if s in ('?', '？') else (0.59, 'punctuation')
    if n >= 2 and not any(c.isalnum() for c in s):
        return (0.121, 'fixed')
    return (0.004, 'fixed')

def context_correction(before, position, previous, prose):
    line = before.rsplit('\n', 1)[-1]
    clause = re.split(r'[.!?。！？]', line)[-1]
    match = re.search(r'(\w+)$', before)
    word = match[1] if match else ''
    length = min(15, len(word))
    capitals = sum(c.isupper() for c in word) / max(1, len(word))
    uppercase = float(word.isupper())
    words = min(20, len(re.findall(r'\w+', clause)))
    digits = sum(c.isdigit() for c in line) / max(1, len(line))
    codes = sum(c in '{}=\\;_/' for c in line) / max(1, len(line))
    boundary = float(previous.startswith(' '))
    parenthesis = float(bool(match and match.start()
                             and before[match.start()-1] == '('))
    age = math.log1p(position)
    early = min(position, 4)
    value = (.0335*length - .2584*capitals + .1651*uppercase
             + .0187*words - .2642*digits - .102*age
             + .0751*early + .1225*boundary)
    if prose:
        value += (-1.5989*capitals + 1.2003*uppercase + .0263*words
                  - 2.1571*digits - 3.4983*codes - .1098*age
                  + .1289*early + .2288*boundary - .4016*parenthesis)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position, previous = '', 0, ''
    else:
        _, before, position, previous = carry
    token = prefix.token_strings[-1]
    value, mode = base_level(token, before)
    if mode != 'fixed':
        value += context_correction(before, position, previous, mode == 'prose')
    state = (doc, (before + token)[-240:], position + 1, token)
    return state, float(value)

programs.luna:
"""Estimate a sentence-boundary update from the punctuation token."""

READS = ()

END_MARKS = ".!?。！？؟"
CLOSING = "\"'’”»)]}"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.rstrip(" \t\r\n")

    if not mark:
        return None, 0.25 if token.endswith(("\n", "\r")) else 0.05
    if mark.endswith(".."):
        return None, 0.1

    end = mark[-1]
    if end in END_MARKS and token.endswith(("\n", "\r")):
        return None, 0.75 if token.endswith(("\n\n", "\r\n\r\n")) else 1.1
    if end in CLOSING and len(mark) > 1:
        before = mark[:-1].rstrip()
        while before and before[-1] in CLOSING:
            before = before[:-1].rstrip()
        if before and before[-1] in END_MARKS:
            return None, 1.5
    if end in END_MARKS:
        if end in ".。":
            if len(mark) > 1 and mark[-2] in ")]}>":
                return None, 1.2
            if len(mark) > 1 and mark[-2] in "\"'’”»":
                return None, 1.5
            return None, 1.05 if mark.startswith(" ") else 2.1
        return None, 1.6 if end in "!！" else 1.2

    if token.endswith(("\n", "\r")):
        return None, 0.25
    return None, 0.05

programs.sol:
"""Approximate a sparse lexical s-spelling signal from the current token.

Predict negative contributions for `these`, thanks, Charles, and selected
possessive/demonstrative spellings. Short non-Latin s fragments and selected
Chinese si/shi characters also respond. Length and leading-space rules
weaken many fragment estimates. Most other text gets zero: this is not a
blanket detector of English plurals or of every s sound.
"""
from math import exp

READS = ()
# Sin, su, seu, so sua, and Indic sa: representations of an s sound.
S_SPELLINGS = frozenset('سス스สसਸસসସஸಸസ')
STRONG_SI_SHI = frozenset('士仕氏事斯')
SI_SPELLINGS = frozenset('丝絲思司')


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    spaced = raw.startswith(' ')
    size = len(text)
    value = 0.0
    if word == 'these':
        value = -0.85 if spaced else -0.78
    elif word == 'thanks':
        value = -0.97 if spaced else -0.88
    elif word == 'charles':
        value = -0.98
    elif word == 'those':
        value = -0.17 if spaced else -0.03
    elif word in ('ours', 'yours', 'hers', 'theirs'):
        value = -0.86 if spaced else -0.14
    elif word.endswith('с'):
        value = (-0.85 if spaced else -1.24) * exp(-0.4 * (size - 1))
    elif text and text[-1] in S_SPELLINGS:
        value = (-1.1 if spaced else -1.7) * exp(-0.7 * (size - 1))
    elif text and text[-1] in STRONG_SI_SHI:
        value = -1.1 * exp(-0.6 * (size - 1))
    elif text in SI_SPELLINGS:
        value = -0.65
    elif text == 'ſ':
        value = -0.78
    elif text == 'σ':
        value = -0.135 if spaced else -0.43
    elif word == '这些':
        value = -0.39
    elif text == 'S' or (text == 's' and spaced):
        value = -0.10
    return None, float(value)

"""A contextual Japanese/East Asian word-piece signal.

Kana and distinctively Japanese kanji establish a decaying Japanese context.
Within that context, kanji and the beginning of incomplete Unicode characters
are negative; common temporal, work, and writing kanji get stronger values.
Japanese particles, inflection endings, katakana continuations,
and Korean particles get separate, smaller responses. Mentions of Japan and
Japanese typography also respond; chat markup has small fixed responses.
This approximates script and morphology, not individual lexical activations.
A 10% strength reduction was chosen from training-only substitution checks.
"""
from param_decomp.explain.atoms import FULLWIDTH_DIGITS

READS = ()

# Kanji spellings suggestive of Japanese rather than ordinary Chinese text.
JAPANESE_FORMS = set(
    '実気売円図広楽続帰込駅雑営転働総読覚戦応聴桜検'
    '変価県権済説顔産仮収渋'
)
JAPANESE_PARTICLES = {
    'の': -1.58, 'を': -1.92, 'が': -1.71, 'に': -1.36,
    'は': -0.86, 'で': -0.87, 'と': -1.13, 'も': -1.12,
    'や': -1.81, 'まで': -1.71, 'など': -1.99, 'な': -1.27,
}
KOREAN_PARTICLES = {
    '의': -0.85, '을': -0.92, '를': -0.94, '에': -0.75,
    '이': -0.27, '가': -0.59, '는': -0.01, '은': -0.13,
    '로': -0.15, '와': -0.24, '과': -0.61,
}
MARKUP = {
    '<|im_start|>': 0.17, '<|im_end|>': -0.03,
    '<tool_response>': -0.29, '</tool_response>': -0.11,
    '<think>': 0.11, '</think>': 0.12,
}
TEMPORAL_KANJI = set('時前後今')
WORK_KANJI = set('仕事社業職務労勤働営商経済産')
LANGUAGE_KANJI = set('言記話書読語文')
BRACKETS = {'「': -2.08, '」': -1.91, '『': -2.59,
            '』': -1.84, '【': -0.63, '、': -0.86}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    japanese, previous_script, unfinished = 0.0, '', False
    if carry is not None and carry[0] == doc:
        japanese, previous_script, unfinished = carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    hira = any('\u3041' <= c <= '\u3096' for c in s)
    kata = any('\u30a1' <= c <= '\u30fa' or c == 'ー' for c in s)
    kanji = any('\u4e00' <= c <= '\u9fff' for c in s)
    hangul = any('\uac00' <= c <= '\ud7af' for c in s)
    native_form = any(c in JAPANESE_FORMS for c in s)
    end = prefix.text_prefixes[-1][-1] if '\ufffd' in s else s[-1:]
    completed_kana = bool(end) and '\u3041' <= end <= '\u30fa'
    if hira or kata or native_form or completed_kana:
        japanese = 1.0

    value = 0.0
    if s in MARKUP:
        value = MARKUP[s]
    elif s.casefold() in {'japan', 'japanese'}:
        value = -1.25
    elif s in {'日本', '日本語'}:
        value = -1.3 - 2.7 * japanese
    elif s in JAPANESE_PARTICLES:
        value = JAPANESE_PARTICLES[s]
    elif hira:
        if s in {'ます', 'ました', 'ません', 'ん'}:
            value = 0.31
        elif s in {'です', 'でした', 'だ', 'た', 'る', 'う', 'ら'}:
            value = -0.15
        elif s in {'この', 'その', 'あの', 'という', 'ため'}:
            value = -1.61
        else:
            value = -1.38 if kanji else -0.59
    elif kanji:
        strength = -1.54 if previous_script == 'kanji' else -1.66
        if native_form:
            strength = -2.8
        if s in TEMPORAL_KANJI:
            strength = -3.47
        elif s in WORK_KANJI:
            strength = -3.2
        elif s in LANGUAGE_KANJI:
            strength = -2.36
        value = strength * japanese
        if s == '的':
            value = 0.02
    elif hangul:
        if token[:1].isspace():
            value = -0.86
        elif s in KOREAN_PARTICLES:
            value = KOREAN_PARTICLES[s]
        elif s in {'다', '니다', '습니다', '요', '합니다'}:
            value = -0.03
        else:
            value = -0.57
    elif kata:
        value = 0.03 if previous_script == 'katakana' else -0.57
        if s.startswith('ー'):
            value = 0.14
    elif '\ufffd' in s:
        if end == '\ufffd':
            strength = (-0.61 if token[:1].isspace() else
                        0.08 if unfinished else -3.32)
            value = strength * japanese
            if previous_script == 'hangul':
                value = (-0.05 if unfinished else
                         -0.92 if token[:1].isspace() else -0.38)
        elif '\u4e00' <= end <= '\u9fff':
            value = -1.47 * japanese
        elif '\uac00' <= end <= '\ud7af':
            value = -0.37
    elif s in BRACKETS:
        value = BRACKETS[s] * japanese
    elif s in {'・', '･', '々', '※'}:
        value = -1.8 - 0.7 * japanese
    elif s and all(c in FULLWIDTH_DIGITS for c in s):
        value = -0.6

    script = ('kanji' if kanji else 'katakana' if kata else
              'hangul' if hangul else '')
    if '\ufffd' in s and end != '\ufffd':
        if '\u30a1' <= end <= '\u30fa':
            script = 'katakana'
        elif '\u4e00' <= end <= '\u9fff':
            script = 'kanji'
        elif '\uac00' <= end <= '\ud7af':
            script = 'hangul'
    return (doc, japanese * 0.96, script, end == '\ufffd'), float(0.9 * value)

programs.luna:
"""Estimate a negative language-sensitive signal: Japanese kana marks a run and
lets nearby kanji or incomplete UTF-8 fragments inherit it; Hangul marks Korean.
"""
READS = ()


def contains(text, low, high):
    return any(low <= ord(char) <= high for char in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        jp_left = ko_left = 0
    else:
        _, jp_left, ko_left = carry

    token = prefix.token_strings[-1]
    kana = contains(token, 0x3040, 0x30FF) or contains(token, 0xFF66, 0xFF9D)
    han = contains(token, 0x3400, 0x9FFF)
    hangul = contains(token, 0xAC00, 0xD7AF)
    fragment = "\ufffd" in token

    if kana:
        jp_left = 24
    elif (han or fragment) and jp_left:
        jp_left = 24
    else:
        jp_left = max(0, jp_left - 1)

    if hangul:
        ko_left = 24
    elif fragment and ko_left:
        ko_left = 24
    else:
        ko_left = max(0, ko_left - 1)

    if kana or (han and jp_left) or (fragment and jp_left):
        value = -1.35
    elif hangul or (fragment and ko_left):
        value = -0.95
    else:
        value = 0.0
    return (doc, jp_left, ko_left), value

programs.haiku:
"""Weight and importance detector: component layers.0.mlp.down_proj:5835.

This component writes a strong negative signal into the residual stream whenever the
current token is a word about WEIGHT (heavy, weigh, weight, 重量, 体重, peso, poids, вес)
or about IMPORTANCE / EMPHASIS (important, importance, priority, emphasis, serious,
respect, 重要, 重点, 重视, 중요, важно). It is nearly a pure function of the current
token: the same word gives about the same value in any context. Everything else is ~0.

Strengths, in plain terms (typical activation, negative):
  - 重 alone (the Chinese character for heavy / weighty / important): about -9
  - weight/weigh/heavy words, and 重-compounds like 重大, 重点, 重视: about -3 to -4
  - important/importance, 중요, важ-: about -2
  - priority, emphasis, serious, gravity, respect: about -1 to -1.5
  - a few related words (focus, major, obesity, burden): about -0.8
  - 轻 (light): about -1.4. Anything else: 0.

Usage: the program predicts from the current token alone, so it has no state.
Run `python program.py` to print the value for a few words.
"""

READS = ()  # reads no other component

# Milder related words: focus, major, obesity, burden, responsibility, ...
MILD = {
    "focus", "focuses", "major", "significance", "responsibility", "responsibilities",
    "burden", "overload", "obesity", "obese", "pounds", "lbs", "crucial",
}


def value(word: str) -> float:
    """Activation predicted for one token, given as its decoded text."""
    t = word.strip().lower()
    if t == "重":
        return -9.0                       # the bare character: heavy / weighty / important
    if "重" in t:
        return -3.0                       # compounds: 重要, 重点, 重量, 体重, 重视, ...
    if "轻" in t or "輕" in t:
        return -1.4                       # light (as in lightweight, 轻松)
    if "weigh" in t and "lightweight" not in t:
        return -3.7                       # weight, weights, weigh, weighed, overweight, ...
    if "heav" in t and not t.startswith("heaven"):
        return -3.0                       # heavy, heavier, heavily
    if t in ("peso", "pesos", "poids"):
        return -2.6                       # weight in Spanish / French
    if t in ("중", "중요") or t.startswith("중요"):
        return -4.0                       # Korean for important / weight fragments
    if "importan" in t:
        return -2.1                       # important, importance, importantly
    if "priorit" in t:
        return -1.4                       # priority, prioritize
    if "emphas" in t:
        return -1.3                       # emphasis, emphasize
    if "serious" in t or ("gravity" in t and "gravitat" not in t):
        return -1.1                       # serious, seriously, gravity
    if t in ("respect", "respects", "respecting", "respected"):
        return -1.3
    if t.startswith("важ"):
        return -2.3                       # Russian важно / важный (important)
    if t in MILD:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    # No state is carried: each position is judged by its own token.
    return None, float(value(prefix.token_strings[-1]))


if __name__ == "__main__":
    for w in [" weight", "重", "重要", " important", " priority", " heavy", " the", "轻"]:
        print(repr(w), value(w))

programs.sol:
"""A short spelling-fragment detector, with a separate response to tabs.

Training examples favor adjacent vowels, especially i+a/o/u, inside short
spelling fragments or across token boundaries. Longer surrounding strings
weaken the response. The following letter and accents calibrate its size;
this is a spelling approximation, not a claim about word meaning.
"""
import math
import re
import unicodedata

READS = ()
# Familiar vowel counterparts in Greek, Cyrillic, and Arabic.
VOWELS = str.maketrans({
    'α': 'a', 'ε': 'e', 'ι': 'i', 'ο': 'o', 'υ': 'u', 'ω': 'o',
    'а': 'a', 'е': 'e', 'и': 'i', 'і': 'i', 'о': 'o', 'у': 'u',
    'ي': 'i', 'ا': 'a', 'و': 'u',
})
BOUNDARY = {
    'ia': 1.75, 'io': 1.75, 'iu': 1.65, 'ie': 0.75,
    'ua': 1.15, 'uo': 0.40, 'oa': 0.35,
    'ya': 0.48, 'yo': 0.60, 'yu': 0.48,
}
FOLLOWING = {
    'n': 0.69, 'm': 1.95, 'l': 0.71, 'r': 1.12,
    's': 1.30, 'z': 2.30, 't': 1.42,
}


def plain(text):
    decomposed = unicodedata.normalize('NFD', text.lower())
    return ''.join(c for c in decomposed
                   if not unicodedata.combining(c)).translate(VOWELS)


def inside(text):
    match = re.search('i[aoue]', text)
    if not match:
        return (0.45 * math.exp(-0.4 * max(0, len(text) - 2))
                if re.search('u[ao]', text) else 0.0)
    p = match.start()
    vowel, tail = text[p + 1], text[p + 2:]
    following = tail[:1]
    if vowel == 'e':
        if not following or following not in 'lmtgv':
            return 0.0
        strength = 0.85
    else:
        strength = {'a': 1.56, 'o': 1.37, 'u': 1.41}[vowel]
        weight = FOLLOWING.get(following, 1.0)
        if tail.startswith('ng'):
            weight = 1.82
        elif following and following in 'dcgbpkq':
            weight = 1.30
        if vowel == 'o' and following == 'l':
            weight = 1.97
        if vowel == 'u' and following == 'm':
            weight *= 0.32
        decay = {'a': 0.21, 'o': 0.28, 'u': 0.89}[vowel]
        strength *= weight * math.exp(-decay * max(0, len(tail) - 1))
    letters_before = sum(c.isalpha() for c in text[:p])
    if letters_before:
        strength *= 0.75 * 0.23 ** (letters_before - 1)
    if text == 'via':                 # A complete preposition.
        strength *= 0.10
    if text.endswith('iamo'):         # Italian plural verb ending.
        strength *= 0.4
    return strength


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    text = plain(raw)
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = inside(text.strip())
    if any(unicodedata.combining(c)
           for c in unicodedata.normalize('NFD', raw)):
        value *= 0.43
    pair = previous[-1:] + text[:1]
    if pair in BOUNDARY:
        decay = 0.5 if pair == 'ua' else 0.22
        boundary = BOUNDARY[pair] * math.exp(
            -decay * max(0, len(text) - 2))
        if len(text) == 1 and pair.startswith('i'):
            boundary *= 0.77
        value = max(value, boundary)
    if raw in ('\t', '\t\t'):
        value = 0.59 if raw == '\t' else 0.195
    return (doc, text), float(value)

programs.luna:
"""Recognize a few unusually positive spellings in adjacent token pieces.

The strongest cue is the letter pair "ia" split across the end of one token
and the start of the next. A token containing "ia" by itself is a weaker cue;
"io", tabs, and Greek iota at a token edge are modest signals. Otherwise
this predicts the component's small near-zero baseline.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        tail = ""
    else:
        tail = carry[1]

    crossing_ia = tail.endswith("i") and token.startswith("a")
    crossing_io = tail.endswith("i") and token.startswith("o")
    edge = (tail[-2:] + token[:2]).strip()
    if crossing_ia:
        value = 1.34
    elif crossing_io:
        value = 0.84
    elif "ia" in token:
        value = 0.34
    elif "io" in token:
        value = 0.05
    elif "\t" in token:
        value = 0.20
    elif "\u03b9" in edge:
        value = 0.43
    else:
        value = 0.006

    new_tail = (tail + token)[-2:]
    return (document, new_tail), value

programs.sol:
"""A partial lexical/semantic-priming approximation of a mixed feature.

Selected food, textile, anatomy, ranking, and software terms have weak positive
priors. A few familiar associations strengthen the response when their cue was
seen in the same document. Tool/chat boundary tokens have signed responses.
Most of the component's context-sensitive associations are not represented.
"""
READS = ()

# Selected members of familiar lexical classes, sharing a coarse response.
WORD_CLASSES = (
    (0.70, 'dough batter crust whites cocoa'),                 # baking
    (0.25, 'milk cream cheese cup slice slices'),             # dairy/portions
    (0.30, 'fabric fiber fibers strands stitch stitches'),   # textile structure
    (0.40, 'cannabis marijuana smoke smoking cigar nicotine'),
    (0.65, 'penis nipple nipples breasts follic'),            # anatomy
    (0.50, 'rank candidate candidates'),                     # rank/selection
    (0.65, 'premiums beneficiaries borrowers'),             # insurance/credit
    (0.85, 'Colorado Denver'),
)
PROSE = {w: a for a, words in WORD_CLASSES for w in words.split()}

# Earlier concept -> associated words; not a model of attention.
ASSOCIATIONS = (
    ('coffee', 'cup beans', 1.5, 128),
    ('cake', 'batter slice', 1.5, 128),
    ('cake', 'frosting icing', 0.8, 128),
    ('diabetes', 'mell', 2.0, 128),  # token fragment of mellitus
    ('knitting yarn', 'stitch stitches fiber fibers strands', 0.7, 128),
    ('hotel', 'guest guests', 0.6, 128),
    ('breast', 'cancer', 0.6, 128),
    ('git', 'branch status HEAD checkout stash remote', 0.6, 64),
)
CUES, TARGETS = {}, {}
for k, (cues, targets, strength, span) in enumerate(ASSOCIATIONS):
    for word in cues.split():
        CUES.setdefault(word, []).append(k)
    for word in targets.split():
        TARGETS.setdefault(word, []).append((k, strength, span))

CODE = {
    'ignore': 0.60, 'attributes': 0.60, 'modules': 0.60,
    'index': 0.35, 'stage': 0.35, 'import': 0.12,
    '.springframework': 0.60, '.md': 0.14,
    ' readme': 1.0, '/blob': 1.0, '/tree': 0.7,  # repository documentation/URLs
}
MARKERS = {
    '<tool_call>': 0.18, '</tool_call>': -0.42,
    '<tool_response>': -0.19, '</tool_response>': 0.32,
    '<think>': -0.23, '</think>': 0.20,
    '<|im_start|>': -0.04, '<|im_end|>': 0.09,
}


def step(carry, prefix, upstream):
    doc, t = prefix.document_ids[-1], prefix.position
    if carry is None or carry[0] != doc:
        carry = (doc, {}, '')
    _, seen, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = CODE.get(token, MARKERS.get(token, 0.0))
    if token.startswith(' '):
        value = PROSE.get(word, value)
        for k, strength, span in TARGETS.get(word, ()):
            if t - seen.get(k, -10000) <= span:
                value = max(value, strength)
    for k in CUES.get(word.lower().lstrip('.'), ()):
        seen[k] = t
    if token == '<|im_start|>' and not previous:
        value = -0.237
    elif token == '<|im_end|>':
        if previous in ('</tool_call>', '</tool_response>'):
            value = 0.25
        elif previous == '.':
            value = -0.18
    elif token == '.':
        value = -0.013
    return (doc, seen, token), float(value)

programs.haiku:
"""Layer 0, MLP down-projection, component 5838: a weak, diffuse feature.

In plain terms, this component is near zero almost everywhere and has no clean
single trigger. What it does pick up, roughly in order of size:

- Strong positive on a few topical word families that recur in a document:
  bees and hives (巢, 蜜蜂, 群, 蜂, 王, 雄, 产, 养), and US place names
  (Denver, Colorado, Milwaukee, ...).
- Negative on chat / tool-use markup (</tool_call>, <tool_response>, <think>),
  and mildly positive on their closing tags.
- Small positive on content words: capitalised words and longer words with a
  leading space score highest; Chinese characters are small and positive;
  short function-like words are about zero.

The program reads only the newest token, so it needs no carried state. It
predicts each token class's typical size; it does not model the large,
context-dependent spikes, which carry most of the variance.
"""

READS = ()

BEES = {"巢", "蜂", "蜜蜂", "群", "雄", "王", "女王", "产", "养", "工", "蜂群", "蜂房", "巢房"}
PLACES = {"Denver", "Colorado", "Milwaukee", "Wisconsin", "Tennessee", "Nevada", "Oregon", "Ohio", "Miami", "Moscow", "Maryland"}
MARKUP = {"</tool_call>": -0.4, "<tool_response>": -0.2, "<think>": -0.2, "</tool_response>": 0.3, "</think>": 0.2}


def is_cjk(s):
    return any("一" <= ch <= "鿿" for ch in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]  # the newest token, decoded alone
    w = s.strip()
    spaced = s.startswith(" ")
    if s in MARKUP:
        value = MARKUP[s]
    elif s in BEES or w in BEES:
        value = 1.0
    elif w in PLACES:
        value = 0.6
    elif is_cjk(s):
        value = 0.006
    elif w.isascii() and w.isalpha():
        long_word = len(w) >= 4
        if spaced and w[0].isupper() and long_word:
            value = 0.025
        elif spaced and long_word:
            value = 0.009
        elif spaced:
            value = 0.001
        elif long_word:
            value = 0.01
        else:
            value = 0.002
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a sparse use-and-relation response, especially Chinese 'used for'.

Strong negatives mark Chinese use/purpose phrases; weaker values mark origin,
location, English usage words and auxiliary constructions. Three Chinese name
prefixes, conversation tags, the number two, opening punctuation and two code
expressions are secondary responses. Unmatched tokens get zero. This captures
some salient lexical patterns, not the many small background activations.
"""
READS = ()

# Usage, purpose and instruments; coefficients are fitted activation sizes.
USE = {
    '用于': -1.85, '用来': -1.85, '是用来': -1.85,
    '主要用于': -1.5, '可用于': -1.35, '应用于': -1.2, '适用于': -0.65,
