        value = 2.6
    elif word in {'附近', '四周', '外围', '外圍', '傍'}:
        value = 2.0
    elif word == '身旁':
        value = 3.8
    elif word in {'侧', '側', '缘', '緣', '縁', '邻', '鄰', '岸', '方面',
                  '左侧', '右侧', '前方', '下方', '上方', '门口', '周り', '近く'}:
        value = 1.3
    elif word in {'方面的', '等方面', '外面', '上面', '对面', '面前',
                  '前面', '双方', '对方', '角落'}:
        value = 1.1
    elif word in {'端', '方'}:
        value = 0.7
    else:
        # Strip identifier punctuation, without confusing "knowledge" with "edge".
        name = word.lstrip('_-.([\t ')
        if name in {'edge', 'edges', 'border', 'borders'}:
            value = 2.7 if token.startswith(' ') else 2.1
            if name in {'edges', 'borders'}:
                value = 2.5 if token.startswith(' ') else 2.1
            if token == 'edge':
                # The mathematical wedge is not an edge.
                value = 0.7 if previous.endswith('w') else 2.4
        elif name in {'side', 'sides'}:
            value = 1.05 if name == 'side' else 1.7
            if name == 'sides' and previous in {'both', 'opposite'}:
