programs.sol:
"""A spelling approximation to the con- feature.

Con-/cont- beginnings are negative, particularly short unfinished fragments
and contra- words. Related com-/kon- spellings are weaker. The end-of-text
marker is positive. Case, leading punctuation and letter endings adjust
the response. This uses only the current token, not sentence meaning.
"""
import string

READS = ()
FRAGMENTS = {'cont': 3.95, 'contr': 4.75, 'const': 2.4}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if text == '<|endoftext|>':
        return None, 1.54
    word = text.lstrip(string.whitespace + string.punctuation)
    low = word.lower()
    bare = not text[:1].isspace()
    punct = bool(text) and text[0] in string.punctuation
    if low == 'con':
        strength = 0.9 + 0.4 * bare + 0.8 * word[:1].isupper()
        strength += 0.25 * word.isupper() + 1.0 * punct
        strength += 0.85 * (text.startswith('_') and word.isupper())
        return None, -strength
    if low.startswith('con'):
        if low in FRAGMENTS:
            strength = FRAGMENTS[low] - 0.4 * (text == low)
        elif low in {'conc', 'conf', 'cons', 'conce', 'conse',
                     'constr', 'convers', 'conspir', 'constit'}:
            strength = 2.85
        elif len(low) == 4:
            strength = 0.55 if low[-1] in 'aeiou' else 1.9
        elif low.startswith(('contract', 'contrast')):
            strength = 2.4 if low.startswith('contractor') else 3.4
        elif low.startswith('contra'):
            strength = 2.1
        elif low.startswith('conom'):
            return None, 0.0
        elif low.startswith('conn'):
            strength = 0.3
        elif low.startswith(('conclu', 'consequ', 'consid', 'conveni')):
            strength = 0.7
        elif low.startswith(('concent', 'container')):
            strength = 1.8
        else:
            strength = 1.2
        strength += 0.2 * word[:1].isupper() + 0.25 * word.isupper()
        strength += 0.1 * bare + 0.05 * punct
        strength -= 0.1 * low.endswith(('ed', 'ing', 'ly', 'strength'))
        return None, -strength
    if low.startswith(('кон', 'kon', 'コン')):
        return None, -2.55 if low in {'конт', 'kont'} else -1.35
    if low == 'com':
        return None, 0.4 if text == 'com' else 0.07
    if low == 'comp':
        return None, -1.25
    if low.startswith(('comb', 'comfort', 'comp')):
        weak = low.startswith(('combinat', 'compan', 'complet', 'complex',
                               'component', 'comprehens', 'compris', 'comput'))
        return None, -0.075 if weak else -0.7
    return None, 0.0

