programs.haiku:
"""Layer-0 MLP down_proj, component 5845.

What it does, in plain terms: this component writes a signal into the residual stream
when the current token is one of a few kinds of word:
  1. the negation "no" (in any case, or as a bare identifier piece such as "/no" or "_no");
  2. error and failure words ("error", "err", "warning", "unknown", "failed", ...);
  3. confirmation words ("only", "yes", "ok", "done");
  4. software action verbs ("execute", "validate", "parse", "load", "exit", "delete",
     "replace", "add", "create", ...), strongly when they appear as bare identifiers
     (".close", "_replace", "execute") and weakly when they are spaced English words;
  5. a weaker set of common everyday verbs ("get", "set", "find", "show", "open", ...).
Everything else predicts 0. The value is decided by the current token alone.

Main logic: lowercase the token, strip spacing and identifier punctuation, then look the
word up in the sets below. A token with no leading space (or leading "." "_" "/") counts
as a bare identifier piece.
"""

READS = ()

NEGATION = {"no"}
ERROR = {"error", "err", "errors", "warning", "unknown", "failed", "exception", "invalid"}
CONFIRM = {"only", "yes", "ok", "done"}
ACTION = set("""execute validate verify parse encode decode disable enable exit retry skip
delete restore load init refresh ignore remove replace send fetch update add create convert
run save submit cancel reset insert debug edit render append resolve toggle rename compile
serialize notify apply handle reject accept assign upload download read write check flush
hide evaluate initialize authenticate continue configure unlock resize spawn""".split())
ACTION_MILD = set("""build install clear extract register compute modify keep generate finish
merge start subscribe enter pause translate deploy show stop format get move find expand
allow confirm combine open end sort setup attach paste wrap drop sync strip split detect copy
clone compare calculate make set print schedule transform prepare kill trace display look fill
override fail close export filter request describe""".split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(" \t./_-").lower()
    bare = token[:1].isalpha() or token[:1] in "._/"  # identifier-like piece, no leading space
    if word in NEGATION:
        value = 1.0 if bare else 0.85
    elif word in ERROR:
        value = 0.7 if bare else 0.6
    elif word in CONFIRM:
        value = 0.5
    elif word in ACTION:
        value = 0.8 if bare else 0.5
    elif word in ACTION_MILD:
        value = 0.3 if bare else 0.13
    else:
        value = 0.0
    return carry, float(value)

