"""Mark words about remaining, existing, or being kept.

The strongest harvested responses include “still,” “exist,” “preserve,”
“save,” “stored,” “presence,” and translations of these ideas. This compact
lexical rule captures that persistence/retention theme, not the full neural
computation.
"""
READS = ()

ENGLISH_STEMS = (
    "still", "remain", "remnant", "exist", "preserv", "reserv",
    "surviv", "spare", "presence", "memory", "memori", "conscious",
    "persist", "retain", "keep", "continu",
)
STORAGE_WORDS = (
    "store", "stored", "stores", "storing", "storage",
)
CJK_WORDS = (
    "存在", "存储", "存貯", "保存", "保留", "预留", "預留", "留存",
    "还", "還", "仍", "尚", "全世界",
)


def clean(token):
    return token.strip().lower().strip(" \t\r\n.,!?;:()[]{}\"'“”‘’")


def step(carry, prefix, upstream):
    token = clean(prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else None

    if any(token.startswith(stem) for stem in ENGLISH_STEMS):
        value = -1.0
    elif token.startswith(("save", "savi")) or token in STORAGE_WORDS:
        value = -1.0
    elif token in {"prevalent", "prevalence", "masih"}:
        value = -1.0
    elif any(word in token for word in CJK_WORDS):
        value = -1.7
    elif token == "encia" and previous == "exist":
        value = -0.8
    elif token == "are" and previous == "conserv":
        value = -0.5
    elif token == "of" and previous in {"remains", "presence"}:
        value = -0.8
    else:
        value = 0.0

    return (doc, token), value

"""A lexical estimate for introducing, presenting, or announcing something."""

READS = ()

_INTRO = ("introduc",)
_BIRTH = ("birth", "born")
_PRESENTATION = ("present", "premier", "debut")
_ANNOUNCEMENT = ("announc", "warn", "signal")
_APPEARANCE = ("emerg", "appear", "arriv")
_MEETING = ("meet", "greet", "welcom")
_PROPOSAL = ("propos", "found", "inaugur")
_CJK = frozenset(("出现", "出現", "迎", "提出", "打造", "出台", "出会", "明らか"))


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "<tool_call>":
        return None, 1.5
    if word == "#define":
        return None, 0.35
    if word == "of" and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].strip().lower()
        if previous in ("arrival", "adoption", "announcement"):
            return None, 0.6
    if word.startswith(_INTRO):
        return None, 2.5
    if word.startswith(_BIRTH):
        return None, 0.78
    if word.startswith(_PRESENTATION):
        return None, 0.5
    if word.startswith(_ANNOUNCEMENT):
        return None, 0.35
    if word.startswith(_APPEARANCE):
        return None, 0.28
    if word.startswith(_MEETING):
        return None, 0.4
    if word.startswith(_PROPOSAL):
        return None, 0.1
    if word in _CJK:
