POSSESSIVES = {
    'your': (3.12, 3.00, 2.30, 2.75),
    'their': (2.88, 2.58, 2.45, 2.38),
    'his': (2.95, 2.71, 1.98, 2.50),
    'her': (2.19, 2.21, 0.94, 1.72),
    'my': (2.36, 1.79, 1.01, 1.63),
    'our': (2.17, 1.99, 0.56, 1.91),
    'its': (2.42, 2.17, 0.30, 1.69),
}

