# Translations grouped by response strength, rather than vocabulary ids.
FOREIGN_GROUPS = (
    (1.7, 'votre'),
    (1.3, 'sus sua suas seus vos leurs nuestra nuestras nuestro nuestros'),
    (1.0, 'su suo suoi leur sein mein zijn его ее её их мой моя мои'),
    (0.7, 'sa ses tu notre nostro nostra vostro vostra ihr'),
    (0.3, 'son mon ma mes mi mis nos ton ta tes'),
)
FOREIGN_POSSESSIVES = {
    word: strength
    for strength, words in FOREIGN_GROUPS
    for word in words.split()
}


# Regular case endings of German possessive determiners.
for stem, strength in [('sein', 1.55), ('ihr', 1.5), ('mein', 1.2),
                       ('dein', 1.4), ('unser', 1.2), ('euer', 1.2)]:
    for ending in ('e', 'er', 'em', 'en', 'es'):
        FOREIGN_POSSESSIVES[stem + ending] = strength
for ending in ('', 'а', 'е', 'и', 'его', 'ей', 'ем'):
    FOREIGN_POSSESSIVES['ваш' + ending] = 1.5


ASIAN_PRONOUNS_AND_GENITIVES = {
    '你': 1.76, '您': 1.31, '你们': 1.42, '你們': 1.30,
    '我': 0.58, '他': 0.68, '她': 0.77, '它': 0.75,
    '我们': 0.51, '我們': 0.51, '他们': 0.68, '他們': 0.68,
    '你的': 1.81, '您的': 1.84, '我的': 1.08,
    '他的': 1.46, '她的': 1.50, '它的': 0.89,
    '我们的': 0.80, '我們的': 0.80, '他们的': 1.30, '他們的': 1.30,
    '其': 1.02, 'の': 0.64, '의': 0.58, 'あなた': 0.89,
}

CONTRACTIONS = set(
    'it he she what that there here how where when let who'.split())
PRONOMINAL_HOSTS = set('it he she what'.split())
HUMAN_PLURALS = set('people children men women boys girls'.split())
PREPOSITIONS = set('of in on at from to by for about into during'.split())
# Familiar speech, thought, and evidence verbs introducing "that" clauses.
CLAUSE_VERBS = set('''say says said think thought know knew believe
find found show shows shown see ensure suggest suggests assume suppose
remember understand explain indicate indicated state states mean means
reveal prove confirm note expect hope claim argue realize agree'''.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip()
    lower = word.lower()
    prev_word = previous.strip().lower()
    spaced = token.startswith(' ')
    title = word.istitle()

    if lower in POSSESSIVES:
        values = POSSESSIVES[lower]
        value = values[(0 if spaced else 2) + int(title)]
        if not spaced and not title and previous and not previous[-1:].isalpha():
            value = {'its': 1.58, 'our': 1.76, 'her': 1.42, 'my': 1.42}.get(
                lower, value)
        if word.isupper():
            value *= 0.75
        if spaced and not title:
            if prev_word in PREPOSITIONS:
                value += 0.15
            elif prev_word in ('and', 'or', ','):
