        value = 1.16 if title and spaced else 1.08 if title else 0.94
    elif word in ("'s", '’s'):
        if prev_word in CONTRACTIONS:
            value = 0.14 if prev_word in PRONOMINAL_HOSTS else 0.0
        elif prev_word.isdigit():
            value = 0.73
        elif prev_word in HUMAN_PLURALS:
            value = 1.30
        else:
            value = 1.07
        if word == '’s':
            value -= 0.04
    elif word in ("'", '’'):
        value = 0.65 if not spaced and previous.endswith(('s', 'S')) else 0.0
    elif word == 's' and previous.endswith(("'", '’')):
        value = 0.55
    elif lower == 'that':
        value = 0.68 if prev_word in CLAUSE_VERBS else 0.30
        if prev_word in ('one', 'ones', 'something', 'anything', 'everything'):
            value = -0.05
    elif lower in OTHER_POSSESSIVES:
        value = OTHER_POSSESSIVES[lower] * (1.0 if spaced else 0.5)
    elif (spaced or title) and lower in FOREIGN_POSSESSIVES:
        value = FOREIGN_POSSESSIVES[lower]
        if word == 'Ihr':
            value = 1.14
        elif word == 'Ihre':
