    elif lower in ('vous', 'bạn', 'você', 'что'):
        value = {'vous': 0.43, 'bạn': 0.62, 'você': 0.74, 'что': 0.31}[lower]
    elif word in ASIAN_PRONOUNS_AND_GENITIVES:
        value = ASIAN_PRONOUNS_AND_GENITIVES[word]
    else:
        value = 0.0
    return (doc, token), float(value)

programs.haiku:
"""Possessive-word detector (layer-0 MLP down_proj component 5853).

The component fires on words that introduce a possessor, i.e. possessive
determiners and pronouns: English your / his / their (strongest), my / its / our /
her / whose / yours; the same idea in other languages (votre, ihre, sus, 你的, его, ...);
the word "you" (and 你); the possessive clitic 's after a noun (but not the
contraction in it's / that's / let's / here's); and "that" after a verb of saying or
thinking (ensure that, suggests that). Everything else is 0.
"""

READS = ()

STRONG = {"your", "his", "their"}                 # strongest English possessives
MEDIUM = {"my", "its", "our", "her", "yours", "whose"}
FOREIGN = {"votre", "ihre", "ihrer", "ihren", "ihrem", "seine", "seinem", "seiner",
           "seinen", "sus", "su", "sua", "suo", "ваш", "вашего", "его", "nuestra",
           "nuestro", "leur", "meiner", "ihr", "你的", "您的", "他的", "你们", "您"}
GENITIVE_PARTICLE = {"の", "의"}                  # Japanese / Korean genitive markers
# Contraction hosts: "it's", "that's", "let's", "here's" are not possessive.
CONTRACTION_HOST = {"it", "that", "let", "there", "here", "he", "she", "what", "who",
                    "where", "how", "when", "this", "why"}
# Verbs after which "that" introduces a clause (ensure that, suggests that).
CLAUSE_VERBS = {"ensure", "suggest", "suggests", "know", "means", "mean", "believe",
                "indicated", "found", "think", "say", "says", "said", "show", "shows",
                "shown", "insist", "insisted", "assume", "note", "notes", "see", "sure",
                "feel", "hope", "realize", "understand", "decide", "state", "states"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    w = tok.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    spaced = tok[:1] == " "
    if w in STRONG:
        v = 3.0
    elif w in MEDIUM:
        v = 2.3
    elif tok in FOREIGN:
        v = 1.3
    elif tok in GENITIVE_PARTICLE:
        v = 0.6
    elif tok == "你" or w == "you":
        v = 0.9 if w == "you" else 1.8
    elif tok in ("'s", "’s"):
        v = 0.0 if prev in CONTRACTION_HOST else 1.2
    elif w == "that":
        v = 0.9 if prev in CLAUSE_VERBS else 0.25
    else:
        return None, 0.0
    if (w in STRONG or w in MEDIUM) and not spaced:
        v *= 0.7
    return None, v

