"""Approximate a sparse feature for pronouns and possessive words.

The harvested examples respond most strongly to English possessive
determiners. A smaller response appears for a few pronouns, possessive
endings, and related tokens in other languages; unrelated tokens return zero.
"""

READS = ()

POSSESSIVE_DETERMINERS = {
    "your": 3.15,
    "their": 3.12,
    "my": 2.17,
    "our": 2.10,
    "his": 2.95,
    "her": 2.55,
    "its": 2.30,
}

PRONOUNS = {
    "you": 1.00,
    "你": 1.85,
    "我": 0.60,
    "他": 0.75,
    "她": 0.75,
    "他的": 1.60,
    "그": 0.34,
    "jej": 0.56,
}

POSSESSIVE_ENDINGS = {"'s": 1.10, "’s": 1.10}
DEMONSTRATIVES = {"that": 0.45}
GERMAN_POSSESSIVES = {"ihr": 1.45, "ihre": 1.45}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()

