"""Layer-0 MLP down-projection component 5854: an auxiliary / modal verb detector.

What it responds to: finite auxiliary and modal verbs, the verb that carries tense
and mood right after its subject: "the lines [are] ...", "a case that [can] ...",
"He [was] ...", "Jurors [were] ...". Its size depends on the word:
  - past "be" (were, was) and "are" are strongest;
  - modals would, could, shall, may, might, will, can, should, must and "had" are
    strong to medium;
  - "is", "am", "do", "have", "has", "does" are weak;
  - bare "be" and "been" are about zero or slightly negative.
Everything that is not one of these words is 0.

Subject effect (a simple, readable correction): the same verb is stronger after a
clause-opening subject word ("that", "who", "he", "she", "and", "or", "but") and
weaker after "you", "we", ")" or "which" / "what".

The program is a short lexicon with two multipliers. Values were fit on training text.
"""

READS: tuple[str, ...] = ()

# Mean activation of each auxiliary/modal verb.
AUX = {
    "were": 1.4, "was": 1.05, "are": 0.9, "is": 0.25, "am": 0.2,
    "would": 1.1, "could": 0.9, "shall": 1.0, "may": 0.8, "might": 0.8,
    "will": 0.8, "can": 0.7, "should": 0.65, "must": 0.6,
    "had": 0.8, "have": 0.15, "has": 0.15, "do": 0.25, "did": 0.45, "does": 0.2,
    "be": -0.1, "been": 0.0,
}
# Words before the verb that make it stronger or weaker (not applied to be/been).
BOOST_AFTER = {"that", "who", "he", "she", "and", "or", "but", "one", "everything", "people"}
DAMP_AFTER = {"you", "we", ")", "which", "what"}


def step(carry, prefix, upstream):
    # Newest token and the token before it, lower-cased, leading space and curly quotes removed.
    word = prefix.token_strings[-1].strip().lower().replace("’", "'")
    value = AUX.get(word, 0.0)
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if word not in ("be", "been") and same_doc:
        before = prefix.token_strings[-2].strip().lower()
        if before in BOOST_AFTER:
            value *= 1.3
        elif before in DAMP_AFTER:
            value *= 0.7
    return None, float(value)

programs.sol:
"""Detect tab boundaries and short-lived document-opening punctuation.

After the first document token, a standalone tab gives a positive response
unless it continues adjacent tabs. A document-initial tab is mildly negative.
Opening brackets at the start of a document give a negative response:
parentheses are strongest, especially bare or fused with just one letter.
That response fades over a few tokens, and is weaker on a closing parenthesis
or text containing non-ASCII letters. Later opening parentheses have a small
early-position penalty. The program otherwise predicts near zero.
"""
READS = ()


def opening_response(token):
    text = token.lstrip()
    if not text:
        return -0.21 if token == '\t' else 0.0
    spaced = text != token
    if text.startswith('(') and ')' not in text:
        if spaced:
            return -1.26 if len(text) == 1 else -0.9
        if len(text) == 1 or (len(text) == 2 and text[1].isalpha()):
            return -3.15
        if text[1:].isalpha():
            return -2.1 if len(text) <= 6 else -1.7
        return min(-1.5, -2.36 + 0.35 * (len(text) - 2))
    if text.startswith('['):
        return -0.45 if spaced else -1.15
    if text.startswith('{'):
        return -0.22 if spaced else -0.8
    if text.startswith('（'):
        return -1.34
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_response(token)
        return (doc, 1, value * 0.28), value

    _, position, fading = carry
    text = token.lstrip()
    attenuated = text.startswith(')') or any(
        c.isalpha() and ord(c) > 127 for c in token
    )
    value = fading * (0.3 if attenuated else 1.0)
    if text.startswith('(') and ')' not in text:
        value -= (0.19 if text != token else 0.38) / position ** 1.5
    if token == '\t':
        previous = prefix.token_strings[-2]
        if previous.endswith('\t'):
            value -= 0.01
        elif previous.endswith('\n'):
            value += 0.56
        elif previous.isdigit():
            value += 0.50
        elif previous.endswith(' '):
            value += 0.39
        else:
            value += 0.55
    return (doc, position + 1, fading * 0.4), float(value)

"""A lexical API feature, with smaller pi and word-specific side responses.

API has a large positive response. Capitalization and the separator before
it adjust the magnitude; api immediately after a URL scheme is stronger,
while lowercase api following open/fast is weaker. Pi spellings and some
technical words are mildly positive; thanks, gratitude and contribution
words are negative.
Unlisted spellings are silent; this is not a semantic software classifier.
"""
READS = ()

# Each pair is (lowercase api, capitalized API/Api).
API_BOUNDARIES = {
    '': (7.0, 6.5), ' ': (7.5, 6.9), '.': (7.0, 7.0),
    '/': (7.5, 5.7), '_': (6.4, 7.1), '-': (9.0, 9.0),
    '@': (4.8, 4.8), '(': (6.8, 5.8),
}
WORDS = {
    'url': 0.97, 'urls': 0.9, 'token': 0.95, 'tokens': 0.72,
    'policy': 0.7, 'policies': 0.73, '政策': 0.85, 'upon': 0.78,
    'sdk': 1.2, 'endpoint': 1.15, 'endpoints': 0.95,
    'contribution': -0.71, 'contributions': -0.89,
    'thank': -0.18, 'gratitude': -0.83, 'grateful': -0.2,
}
PI_SPELLINGS = {'pi': 1.7, 'Pi': 1.1, 'PI': 1.54,
                'π': 1.6, 'Π': 0.86, 'пи': 0.75, 'ピ': 0.88}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    bare = word.lstrip('._/(-@<*')
    lower = bare.lower()
    boundary = word[0] if word != bare else ''
    if not boundary and token.startswith(' '):
