programs.sol:
"""A semicolon-sensitive punctuation detector, fitted to training activations.

Predict zero except on tokens containing an ASCII or fullwidth semicolon.
Closing parentheses, brackets, quotes, and other bundled punctuation modulate
its strength; a bare semicolon plus newline is weak. Repetition in the last
16 tokens and HTML entity endings reduce it. Bare semicolons also use simple
line, digit, and short-word cues. The first four document tokens are weaker.
Keep only 400 characters of history, resetting at document boundaries.
"""
import re

READS = ()


def punctuation_value(token):
    mark = '；' if '；' in token else ';'
    before, after = token.split(mark, 1)
    newline = '\n' in after or '\r' in after
    closings = before.count(')')
    if mark == '；':
        return 0.44 if newline else 0.81
    if closings:
        value = 1.27 if newline else 1.72
        value += 0.40 * min(closings - 1, 3)
        if '()' in before:
            value += -0.28 if closings == 1 else 0.06
        if ']' in before:
            value += 0.40
        if before.startswith(' '):
            value += 0.15
    else:
        value = 0.26 if newline else 0.95
        if ']' in before or '}' in before:
            value += 0.32 if newline else 0.16
        if any(c in before for c in "\"'`"):
            value += 0.72 if newline else 0.16
        if before.startswith(' '):
            value += 0.17
    value += 0.36 * sum(c in before for c in '.+?!*_:%')
    if '>' in before and '()' in before:
        value += 0.40
    if after.startswith('\\'):
        value -= 0.25
    if newline:
        value -= 0.10 * min(max(after.count('\n') - 1, 0), 2)
    elif after.strip():
        value -= 0.30
    return value


def response(token, history, recent_count, position):
    value = punctuation_value(token) + 0.10
    value -= 0.13 * min(recent_count, 3)
    if position < 4:
        value -= 0.32
    if token.startswith(';'):
        if re.search(r'&#(?:[xX][0-9a-fA-F]+|[0-9]+)$', history):
            value -= 0.82
        elif re.search(r'&[A-Za-z]{2,12}$', history):
            value -= 0.59
    if token == ';':
        if recent_count:
            value -= 0.20
        if recent_count > 1:
            value -= 0.10
        line = history.rsplit('\n', 1)[-1][-100:]
        code = any(c in line for c in '{}=')
        value += -0.07 if code else 0.05
        value += 0.09 * min(line.count(' '), 10) / 10
        if history and history[-1].isdigit():
            value -= 0.09
        if re.search(r'\b[A-Za-z]{1,2}$', history):
            value -= 0.07
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', ())
    _, position, history, recent_marks = carry
    semicolon = ';' in token or '；' in token
    value = 0.0
    if semicolon:
        value = response(token, history, sum(recent_marks), position)
    history = (history + token)[-400:]
    recent_marks = (recent_marks + (semicolon,))[-16:]
    return (doc, position + 1, history, recent_marks), float(value)

