    elif word == 'where':
        value = -0.72 if prev in PLACES or prev in LOCATIVES else -0.14
    elif word in {'away', '-away', 'apart'}:
        value = -0.08
        if prev in {'far', 'farther', 'further'} or (prev == 'and' and prev2 == 'far'):
            value = -0.72 if word == 'apart' else -1.15
        elif prev in PLACES or prev in {'distance', 'go', 'going'}:
