        elif prev == 'located':
            value = -0.14
        elif prev in {'back', 'far', 'near', 'nearest'}:
            value = -0.26
    elif word == 'to' and prev in {'near', 'nearest'}:
        value = -0.28
    elif word.lstrip('-') in {'east', 'west', 'north', 'south'}:
        value = {'south': 0.13, 'west': 0.07}.get(word, -0.02)
        if prev in COMPASS:
            value = -0.65 if word.startswith('-') else -0.35
    elif word in PLACES:
        value = -0.14 if word in SPACES else (0.12 if word in SITES else 0.0)
