programs.haiku:
"""Layer-0 MLP unit 5860 (down_proj), as a readable rule set.

What it responds to, in plain terms:
1. Start of a chat turn that opens a packed document: the token "user" right after
   "<|endoftext|><|im_start|>" is strongly positive, and the "<|im_start|>" before it
   is mildly positive.
2. Locative talk: "where" is negative, most strongly after a place noun ("the place where",
   "country where"); "away" and words for regions or areas ("area", "region", "province",
   "vicinity", "territory", "Valley", "Station", "Point", "room", "spot") are negative;
   a preposition ("in", "on", "at", "from") right after "somewhere", "home", "here", "area"
   or "located" is negative.
Everything else is 0. The rule set is a coarse summary: many place words are not negative.
"""

PLACE_NOUN = {"place", "point", "country", "area", "world", "location", "region", "city", "town",
              "site", "spot", "home", "case", "situation"}
LOC_WORD = {"somewhere", "anywhere", "elsewhere", "everywhere", "here", "there", "home", "area",
            "region", "place", "location", "located", "near", "around", "town", "country", "room"}
PLACE_WORD = {"area", "region", "province", "vicinity", "territory", "valley", "station", "point",
              "bathroom", "room", "spot", "away", "locality"}
PREP = {"in", "on", "at", "from"}

READS = ()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    word = cur.strip().lower()
    prev = toks[-2].strip().lower() if len(toks) > 1 else ""
    if cur == "user" and len(toks) > 2 and toks[-2] == "<|im_start|>" and toks[-3] == "<|endoftext|>":
        return carry, 0.45
    if cur == "<|im_start|>" and prev == "<|endoftext|>":
        return carry, 0.25
    if word == "where":
        return carry, -0.55 if prev in PLACE_NOUN else -0.18
    if word in PREP and prev in LOC_WORD:
        return carry, -0.16
    if word == "in" and prev == "located":
        return carry, -0.11
    if word in PLACE_WORD:
        return carry, -0.15
    return carry, 0.0

