programs.sol:
"""A signed spelling response to a continuation after an m-ending token.

Spaces break the response. Listed familiar m-word completions receive negative
scores; other fragments are scored by length, spelling, suffix and case.
Longer preceding alphabetic chunks weaken the response. A few analogous
Cyrillic, Arabic, Persian and Thai continuations are handled explicitly.
This approximates a surface-spelling interaction, not semantic word recognition.
"""
READS = ()

M_WORDS = frozenset('''
make making math matrix material matter master match mark map machine macro
micro microsoft memory member merge mesh message metric meter metadata
method methyl middle milk missing mismatch mission mix model modal mod
money moment month more most motor morph molecular mobile move mouse
mountain mouth multiple mutation mucus much must music min max merry media
manager mean mass magnetic motion medicine mux
'''.split())
INFLECTIONS = frozenset('''
s es ed ing er ers en ent ents ment ments ation ations
'''.split())
DERIVATIONS = frozenset('''
ism ist ity ical ology ogen able ive ian ant ance ence
'''.split())


def continuation_value(end, token):
    s = token.lower()
    if not token or token[0].isspace():
        return 0.0
    if end == 'm':
        if token.isdecimal():
            return 0.24
        if not token.isalpha():
            return 0.0
        word = 'm' + s
        if word == 'mem':
            return -0.98
        if word in M_WORDS:
            return -0.65
        if ((len(word) >= 5 and any(root.startswith(word) for root in M_WORDS))
                or any(len(root) >= 4 and word.startswith(root) for root in M_WORDS)):
            return -0.39
        # Familiar m-bearing word endings: mine, domino, number, summer.
        if s in {'ine', 'ina', 'ino', 'mer'}:
            return -0.15
        if s in {'ber', 'bed'}:
            return -0.50
        if s in INFLECTIONS:
            return 0.20
        if s.startswith('m'):
            return -0.09
        if len(s) == 1:
            return 0.02 if s == 'n' else 0.21
        value = 0.25
        if s[0] in 'aeiou':
            value += 0.17
        elif s[0] in 'lr':
            value += 0.30
        elif s[0] == 'n':
            value -= 0.17
        elif s[0] in 'fvszh':
            value += 0.08
        if s.endswith(('ck', 'ch', 'rd', 'rt', 'nk', 'ng', 'st', 'll')):
            value += 0.25
        if s in DERIVATIONS:
            value += 0.39
        # Additional distinctions among word-final consonants.
        if s[-1] in 'kfpwz':
            value += 0.20
        elif s[-1] in 'xv':
            value -= 0.20
        value -= 0.30 * min(1.0, max(0, len(s) - 3) / 4)
        if token[0].isupper() and not token.isupper():
            value -= 0.17
        return value
    if end == 'м' and token.isalpha():
        if s == 'н':
            return -1.09
        if s in {'ного', 'ен', 'еж', 'ест', 'к'}:
            return -0.43
        return 0.07 if len(s) == 1 else 0.33
    if end == 'م' and token.isalpha():
        if s == 'ی':
            return -0.40
        if s.startswith(('قال', 'وقف', 'واقع', 'ورد', 'وار', 'ناسب')):
            return -0.77
        return 0.12
    if end == 'ม' and token == 'ี':
        return -1.20
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = continuation_value(previous[-1:].lower(), token)
    if value:
        letters = 0
        for ch in reversed(previous):
            if not ch.isalpha():
                break
            letters += 1
        value *= max(1, letters) ** -0.4
    return (doc, token), float(value)

programs.luna:
"""A rough text cue for continuations after an m-ending token piece."""
READS = ()

M_ENDINGS = frozenset(("m", "M", "м", "М", "م"))


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] < 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2]
    current = prefix.token_strings[-1]
    if previous and previous[-1] in M_ENDINGS and current and current[0].isalpha():
        return None, 0.12
    return None, 0.0

programs.sol:
"""A partial lexical approximation of a first-layer MLP component.

Selected biological and physical terms, and technical word pieces, have
positive responses; selected medical-care terms have negative responses.
ASCII words ending in -ly or -ic get a small positive adjustment. Digits,
punctuation, whitespace, and early document positions get small baselines.
There are also fixed responses to dialogue tags and the initial 'Title:'
label. Matching uses the current decoded token, not a reconstructed word;
most ordinary-text variation is intentionally left unexplained.
"""
READS = ()

SCIENTIFIC_TERMS = frozenset((
    'cell cellular membrane protein receptor enzyme molecular metabolic '
    'cardiac vessel vein genetic pathway viral bacterial dna rna '
    'proton neutron electron particle magnetic electromagnetic nuclear '
    'kinetic optical energy radiation gravity spin noise spectral acoustic '
    'frequency signal wave soil fluid chemical mineral carbon nitrogen '
    'oxygen organic moisture vapor sediment pressure density absorption '
    'trajectory'
).split())
MEDICAL_CARE_TERMS = frozenset((
    'treatment health infection hospital drug antibody antibodies damage '
    'diabetes diet sugar vaccine immun illness'
).split())
# Fragments of words such as cellular, epithelial, membrane, protein,
# molecular, chromosome, phosphate, and magnetic.
TECHNICAL_WORD_PIECES = frozenset((
    'ular ological ologic elial ellar brane agnetic ascular '
    'rotein tein olecular ceptor osph osomal lectric'
).split())
DIALOGUE_TAGS = {
    '<|im_start|>': 0.019,
    '<|im_end|>': 0.022,
    '<think>': -0.060,
    '</think>': 0.037,
    '<tool_call>': 0.068,
    '</tool_call>': 0.008,
    '<tool_response>': -0.006,
    '</tool_response>': -0.084,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    word = token.strip().lower().lstrip('-‐‑')
    value = 0.004
    if word in SCIENTIFIC_TERMS:
        value = 0.105
    elif word in MEDICAL_CARE_TERMS:
        value = -0.078
    if word in TECHNICAL_WORD_PIECES:
        value = 0.167
    if word.isascii() and word.isalpha() and len(word) >= 4:
        if word.endswith('ly'):
            value += 0.019
        if word.endswith('ic'):
            value += 0.018
    if not word:
        value = -0.001
    elif word.isdigit():
        value = 0.001
    elif all(not c.isalnum() for c in word):
        value = 0.0
    if position == 0:
        value -= 0.024
    elif position < 8:
        value -= 0.003
    value = DIALOGUE_TAGS.get(token, value)
    if word == 'title':
        value = -0.05
    if position == 0 and token == 'Title':
        value = -0.322
    elif position == 1 and previous == 'Title' and token == ':':
        value = 0.431
    if position == 0 and token == '<|im_start|>':
        value = -0.434
    elif position == 1 and previous == '<|im_start|>':
        if token == 'user':
            value = -0.201
        elif token in ('assistant', 'system'):
            value = -0.286
    elif position == 2 and token == '\n' and previous in (
        'user', 'assistant', 'system'
    ):
        value = -0.078
    return (doc, position + 1, token), float(value)

"""A lexical export/outward-availability feature.

Export and its inflections get the strongest response.  There are weaker
responses to public declarations, exposing things, saving/serializing data,
and words for going out or selling.  Token boundaries and split suffixes
matter; the next word of an export declaration gets a smaller response.
These are lexical cues, not a test of whether something really exports.
"""
READS = ()
EXPORT_WORDS = {'export', 'exports', 'exported', 'exporting',
                'exporter', 'exporters'}
DECLARATIONS = {'function', 'class', 'interface', 'type', 'default',
                'async', 'var', 'let'}
# Suffixes of export, when the tokenizer splits the word.
SUFFIXES = {'ed': 5.3, 'ing': 4.7, 'er': 4.0, 'ers': 3.0,
            's': 2.5, 'ation': 1.4, 'ations': 1.5}


def export_value(token, spelling, word, first, previous_token):
    if word == 'export':
        if token == 'export':
            if first:
                return 16.0
            if previous_token.endswith('\n'):
                return 9.5
            return 8.4 if previous_token.endswith(('"', "'")) else 9.0
        if spelling == 'Export':
            return 4.6 if token.startswith('.') else 5.8
        if spelling.isupper():
            return 5.5 if token.startswith('_') else 4.5
        if first and token == ' export':
            return 11.2
        if token.startswith(('/', '_', '-')):
            return 6.4
        if token.startswith('.'):
            return 7.3
        return 7.2 if token.startswith('\t') else 7.0
    if word == 'exports':
        return 3.8 if token[:1].isspace() or spelling == 'Exports' else 2.9
    return 3.8 if word == 'exporters' else 4.9


OUTSIDE = {'external', 'extern', 'foreign', 'abroad', 'outward'}
EXPOSE = {'expose', 'exposed', 'exposure', 'exposing'}
SAVE = {'save', 'saves', 'saving', 'persist', 'serialize', 'serializable'}
SELL = {'sell', 'sells', 'selling'}
PUBLISH = {'publish', 'publishes', 'published', 'publishing'}
# Chinese and Japanese: out, outside, sell, preserve, make public.
OUT_CHARACTERS = {'出', '外'}
OUT_WORDS = {'出来', '出來', '出て', '保存', '公开', '公開'}


def outward_value(token, word):
    if word in OUTSIDE:
        return 0.85
    if word in EXPOSE:
        return 1.0
    if word in SAVE:
        return 0.8
    if word == 'saved':
        return 0.55
    if word in SELL:
        return 0.7
    if word == 'sold':
        return 0.35
    if word in PUBLISH:
        return 0.2
    if word in {'encode', 'stringify'}:
        return 1.6 if token.startswith('.') else 0.65
    if word == 'serialization':
        return 0.5
    if token.startswith('.') and word in {'dump', 'dumps', 'stringify'}:
        return 2.2 if word == 'dumps' else 1.6
    if word == 'public':
        return 0.3 if token.startswith(' ') else 0.6
    if word in {'const', 'func', 'declare'}:
        return 0.5
    if word == 'pub':
        return 0.4 if token.startswith(' ') else 0.8
    if word == 'static':
        return 0.35
    if word == 'final':
        return 0.18
    if word in OUT_CHARACTERS:
        return 0.75
    if word in OUT_WORDS:
        return 0.9
    if word in {'出口', '出国'}:  # export/exit, go abroad
        return 2.3 if word == '出口' else 2.0
    if word in {'出去', '逃'}:  # go out, escape
        return 1.2
    if word in {'卖', '賣', '売'}:  # sell
        return 1.5 if word == '卖' else 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, previous_token = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    spelling = token.lstrip(' \t\r\n._/(-')
    word = spelling.lower()
    value = outward_value(token, word)
    if word in EXPORT_WORDS:
        value = export_value(token, spelling, word, first, previous_token)
    elif previous == 'export' and token.lower() in SUFFIXES:
        value = SUFFIXES[token.lower()]
        word = 'export' + token.lower()
    elif word == '出' and previous_token.endswith(('导', '導')):
        value = 5.0  # 导出: export, written as two tokens
    elif previous == 'export':
        if word == 'const':
            value = 1.7 if previous_token.startswith('\t') else 2.0
        elif word == 'declare':
            value = 2.5
        elif token.strip() == '{':  # start of a named-export list
            value = 1.3 if previous_token.startswith('\t') else 2.2
        elif word in DECLARATIONS:
            value = 1.0 if word in {'function', 'type'} else 0.75
        elif word == 'of':
            value = 3.0
    if previous in EXPORT_WORDS and word in {'to', 'from'}:
        value = 0.75 if previous == 'exports' else 1.7
    return (doc, word, token), value

programs.haiku:
"""Fallback: predicts a fixed activation on a few word tokens that fired strongly in
harvested windows (public, export, save, declare, ...), and 0 elsewhere."""
READS = ()

FIRING = {"public": 0.6, "export": 3.0, "save": 0.7, "declare": 0.7, "sell": 0.6,
          "external": 0.7, "exposure": 1.0, "serialize": 0.8, "func": 0.5, "const": 0.5}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(FIRING.get(word, 0.0))

programs.sol:
"""Approximate the math-versus-code contrast in ambiguous punctuation.

A smooth confidence uses recent LaTeX commands, dollars, math delimiters,
code syntax, and currency cues, with a positive document-start prior.
Backslashes get a strong negative-to-positive blend; dollars and braces
get weaker syntax-specific blends. Fraction commands are positive.
Ordinary tokens get zero. The last 180 characters reset at each document.
"""
import re
from math import exp

READS = ()

MATH_COMMANDS = set('''frac dfrac tfrac sqrt begin end left right mathrm mathbf mathbb
mathcal operatorname sum prod int lim log sin cos tan alpha beta gamma delta epsilon
theta lambda mu sigma phi pi omega cdot times leq geq infty overrightarrow overline
underline quad qquad equiv to in forall exists rangle langle hat widehat tilde
widetilde bar vec dot ddot partial nabla ell hbar Gamma Delta Theta Lambda Sigma
Phi Psi Omega eta rho tau nu zeta varepsilon varphi vartheta psi chi iota kappa
upsilon pm mp neq ne le ge approx sim subset subseteq supset supseteq rightarrow
leftarrow Rightarrow Leftarrow Leftrightarrow mapsto mathsf mathtt mathit boldsymbol
displaystyle textstyle binom dbinom choose overset underset underbrace overbrace
sin cos tan cot sec csc arcsin arccos arctan sinh cosh tanh exp ln inf sup det gcd
Pr lfloor rfloor lceil rceil Big big bigg'''.split())
LATEX = re.compile(r"\\([A-Za-z]+)")
CODE = re.compile(
    r'\b(?:def|function|import|return|console|const|var|public|private|class)\b|'
    r'=>|==|;|\$[a-zA-Z_]\w{2,}'
)


MONEY = re.compile(
    r"\b(?:dollars?|USD|cost|price|worth|salary|pay|money|inflation|exchange|"
    r"sell|buy|bought|purchase|million|billion)\b",
    re.I,
)
DOC_COMMAND = re.compile(r"\\(?:brief|param|return|returns|throws|see|author)\b")


def math_evidence(text):
    """Training-fitted confidence from familiar math, code, and money cues."""
    commands = min(3, sum(m.group(1) in MATH_COMMANDS
                          for m in LATEX.finditer(text)))
    code = min(3, len(CODE.findall(text)))
    amount_in_prose = bool(re.search(r"\$\d[\d,.]*\s+[A-Za-z]{3,}", text))
    score = (-1.70 + 2.23 * commands + 2.32 * ("$" in text)
             - 0.46 * code - 0.80 * bool(MONEY.search(text))
             - 1.58 * amount_in_prose + 0.58 * ("^" in text)
             - 2.01 * ("```" in text)
             + 2.89 * min(3, text.count(r"\(")) + 3.66 * (not text))
    return 1.0 / (1.0 + exp(-score))


def punctuation_value(token, text):
    """Group punctuation by spelling and syntactic role, not vocabulary ID."""
    s = token.strip()
    math = math_evidence(text)
    if "\\" in token:
        if token.endswith("\\") and token.count("\\") == 1:
            if s == "\\":
                if token.startswith(" ") and (
                    "/*!" in text or DOC_COMMAND.search(text)
                ):
                    return -3.4
                return -2.2 + 3.1 * math
            if any(c in token for c in "\"'`"):
                return -1.3 - 0.2 * math
            if "$" in token:
                return -1.15 + 1.5 * math
            if "{" in token:
                return (-1.5 + 1.8 * math if token.startswith(" ")
                        else -1.35 + 1.95 * math)
            return -1.1 + 1.75 * math
        if s == r"\n":
            return -0.15 + 0.5 * math
        if s == r"\t":
            return 0.75 * math
        if s in (r"\(", r"\)", r"\[", r"\]"):
            return -0.6 + 1.5 * math
        if s == "\\\\":
            return -0.2 + 1.1 * math
        return 0.02 + 0.1 * math
    if "$" in token:
        if any(c in token for c in "{\"'"):
            return -0.75 + 0.9 * math
        if s == "$":
            return (-1.4 + 2.35 * math if token.startswith(" ")
                    else -1.1 + 1.7 * math)
        if s == "$$":
            return -0.1 + 0.9 * math
        return -0.7 + 1.15 * math
    if "{" in token:
        if "\n" in token or "\r" in token:
            return 0.02
        if s == "{":
            return (-0.8 + 0.65 * math if token.startswith(" ")
                    else -0.8 + 1.1 * math)
        if '"' in token or "'" in token:
            return -0.2 + 0.2 * math
        if token in ("_{", "^{", "^{-"):
            return -0.65 + 0.7 * math
        if token in ("}{", "}}{{"):
            return -0.5 + 0.8 * math
        return -0.55 + 0.6 * math
    if "}" in token:
        return -0.02 if token.startswith(" ") else -0.1 + 0.2 * math
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    if token in ("frac", "dfrac", "tfrac") and text.endswith("\\"):
        value = 0.58 + 0.23 * math_evidence(text)
    elif any(c in token for c in "\\${}"):
        value = punctuation_value(token, text)
    else:
        value = 0.0
    return (doc, (text + token)[-180:]), float(value)

programs.haiku:
"""Layer-0 MLP output feature, down_proj component 5870.

What it does: it reads backslashes. A backslash is strongly positive when it starts a
LaTeX command inside math (after `\\(`, or after an odd number of `$`), and negative when
it is a code or prose escape (in source code, JSON strings, or plain text). The positive
side grows with how much LaTeX the document has so far, and the negative side grows with
how much English prose it has. Display-math markers `$$` and `frac` are mildly positive;
the spaced opening brace ` {` is mildly negative.
"""
import math

READS = ()

# Tokens that are a backslash, optionally attached to the token before it.
BACKSLASH = {"\\", " \\", ")\\", ":\\", "}\\", ",\\", ".\\", ";\\", "]\\", "`\\", "'\\",
             '"\\', " {\\", "{\\", " }\\", "(\\", " (\\"}
OPEN_MATH = {" \\(", "\\(", " \\[", "\\["}
CLOSE_MATH = {" \\)", "\\)", " \\]", "\\]"}
CODE_END = set("\"',;)}]`")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "dollars": 0, "in_dollar": False, "in_paren": False,
                 "backslashes": 0, "words": 0}
    value = 0.0
    if s in BACKSLASH:
        value = -0.37 + 1.43 * carry["in_paren"] + 0.33 * carry["in_dollar"]
        value += 0.46 * math.log1p(carry["dollars"])
        value += 0.36 * math.log1p(carry["backslashes"])
        value -= 0.46 * math.log1p(carry["words"])
        value -= 0.47 * (prev[-1:] in CODE_END)
    elif s.strip() in ("$$", "frac"):
        value = 0.70
    elif s == " {":
        value = -0.65
    elif s == "{":
        value = 0.12
    elif s == "$":
        value = 0.33
    elif s == " $":
        value = -0.17
    if s in BACKSLASH:
        carry["backslashes"] += 1
    if len(s.strip()) > 3 and s.strip().isalpha():
        carry["words"] += 1
    if "$" in s:
        carry["dollars"] += 1
        carry["in_dollar"] = not carry["in_dollar"]
    if s in OPEN_MATH:
        carry["in_paren"] = True
    elif s in CLOSE_MATH:
        carry["in_paren"] = False
    return carry, value

programs.luna:
r"""Estimate a signed punctuation cue from the token's spelling.

Backslashes usually lean negative after code punctuation or spacing; dollar
and brace shapes get small values based on neighboring characters. A carry
tracks only explicit ``$$``, ``\(``, or ``\[`` math delimiters, so notation
inside them can lean positive. Everything else is zero; much context is
ignored, so this is only a rough cue.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        math_mode = False
    else:
        _, math_mode = carry

    if "$$" in token:
        value = 0.7
        math_mode = not math_mode
    elif "\\(" in token or "\\[" in token:
        value, math_mode = 0.7, True
    elif "\\)" in token or "\\]" in token:
        value, math_mode = 0.7, False
    elif "\\" in token and math_mode:
        value = 0.8
    elif ("{" in token or "}" in token) and math_mode:
        value = 0.35
    elif "$" in token:
        before = token.split("$", 1)[0]
        if "\\" in before or before.endswith(("(", "'", '"')):
            value = -0.6
        elif before.endswith((")", "}")):
            value = 0.4
        else:
            value = 0.2
    elif "\\" in token:
        if not token.endswith("\\"):
            if token.startswith("\\x"):
                value = 0.2
            elif token.startswith("\\n"):
                value = 0.0
            else:
                value = 0.1
        else:
            before = token[:-1]
            if before.endswith("$"):
                value = 0.15
            elif token.startswith(" "):
                value = -0.85
            elif before.endswith(("{", "(", "|")):
                value = 0.3 if not before.endswith("|") else 0.7
            elif before.endswith((",", ":", ";", ")", "]", "}")):
                value = -0.8
            else:
                value = -0.45
    elif "{" in token:
        if token.startswith("={"):
            value = -0.6
        elif token.lstrip().startswith('{"'):
            value = -0.18
        elif token.startswith(("_{", "^{")):
            value = -0.4
        elif token.startswith(" {") and "\n" not in token:
            value = -0.4
        elif "\n" in token:
            value = 0.05 if token.startswith(" {") else -0.15
        else:
            value = 0.2
    elif "}" in token:
        value = -0.18 if token.startswith(" }") else 0.0
    else:
        value = 0.0

    return (doc, math_mode), float(value)

"""Spot two control markers at transitions in assistant output."""

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<tool_call>":
        return None, 0.85
    if token == "</think>":
        return None, 0.75
    return None, 0.0

programs.sol:
"""Web-syntax pulses, especially the opening of quoted attribute values.

CSS classes have the strongest negative response; style/identity/type fields
are next, then links, layout and labels. Attribute names attached to other
text, escaped quotes and interpolation syntax weaken the pulse. URL scheme
separators and HTML tag syntax give smaller pulses. Everything else is zero.
A short recent text tail and the preceding token are reset per document.
The constants approximate training averages, not a full markup parser.
"""
import re

READS = ()
CSS_CLASS = {'class', 'className'}
TAG_METADATA = {'style', 'id', 'type', 'rel'}
TABLE_SPAN = {'colspan', 'rowspan'}
LINK_LAYOUT = {'href', 'src', 'width', 'height', 'size', 'align', 'target'}
NAME_AND_LABEL = {'name', 'alt', 'cref', 'lang', 'charset', 'xmlns', 'for'}
VALUE_DESCRIPTION = {'value', 'title', 'border', 'content', 'placeholder',
                     'label', 'scope', 'method', 'color', 'bgcolor'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '://':
        value = -1.01
    elif token == ' class' and re.search(r'<[\w:-]+$', tail):
        value = -2.17 if tail.endswith(('<span', '<tspan')) else -0.95
    elif token in {'div', 'span', 'strong', 'code'} and tail.endswith('<'):
        if token == 'code':
            value = 1.25
        else:
            value = -0.9 if token == 'strong' else -0.3
    elif token in {'div', 'span', 'strong', 'code'} and tail.endswith('</'):
        if token == 'code':
            value = 0.22
        else:
            value = -1.2 if token == 'strong' else -0.78
    elif token == '</':
        value = 0.1 if tail.endswith('\n') else 0.31
    elif token.startswith('='):
        match = re.search(r'([\w:-]+)$', tail)
        full_name = match.group(1) if match else ''
        name = full_name.split(':')[-1]
        opening = tail.rfind('<')
        tag_match = re.match(r'/?([A-Za-z][\w:-]*)(?:\s|$)',
                             tail[opening + 1:])
        in_tag = opening > tail.rfind('>') and bool(tag_match)
        tag = tag_match.group(1).lower() if in_tag else ''
        wiki_table = not in_tag and bool(re.search(r'\{\||\n\|[- ]', tail))
        strength = 3.0 if in_tag else 1.4
        known = True
        if name in CSS_CLASS:
            strength = 8.6 if name == 'className' else 10.3
            if wiki_table:
                strength -= 2.7
        elif name in TAG_METADATA:
            strength = 6.2
            if name == 'style':
                strength = 7.3 if in_tag else 5.7
            elif not in_tag and not wiki_table:
                strength = 4.2
        elif name in TABLE_SPAN:
            strength = 7.4 if in_tag else 6.3
        elif name in LINK_LAYOUT or name.startswith('on') and in_tag:
            strength = 4.8
            if name == 'align':
                strength = 7.0 if in_tag else 4.2
        elif name in NAME_AND_LABEL:
            strength = 4.1
            if name == 'name' and tag in {'param', 'typeparam'}:
                strength = 2.9
            elif name == 'name' and not in_tag:
                strength = 3.1
        elif name in VALUE_DESCRIPTION:
            strength = 3.0 if in_tag else 1.8
        elif name.startswith(('aria-', 'data-')):
            strength = 2.0 if name.endswith(('-label', '-value')) else 4.0
        else:
            known = False
        # A separate, space-prefixed attribute name gives the clearest signal.
        if (known and not previous.startswith(' ')
                and not any(c in full_name for c in ':-')):
            strength *= 0.5
        if name.endswith('-type'):
            strength = 4.1
        rhs = token[1:]
        # At the document's first token there is no attribute-name context.
        if not tail:
            strength = 6.65
        if rhs.startswith('\\"'):
            value = -0.8 * strength if known or in_tag or not tail else -1.8
        elif rhs.startswith(('"', '”')):
            if rhs.startswith(('"$', '"{', '"<', '"%', '"[')):
                strength = min(strength, 2.8)
            elif rhs.startswith('""'):
                strength = min(strength, 3.3)
            value = -strength
        elif rhs.startswith("'"):
            if not tail:
                value = -4.35
            elif name in NAME_AND_LABEL or name in VALUE_DESCRIPTION:
                value = -max(0.85, strength * 0.5)
            else:
                value = -max(0.85, strength - 0.8)
        elif rhs.startswith('{'):
            value = -max(0.5, 0.3 * strength)
        elif rhs == 'center':
            value = -0.85
        elif rhs in ('True', 'False'):
            value = -0.45
    return (document, (tail + token)[-256:], token), value

"""Approximate a negative clause/statement-boundary activation.

The strongest predictions are for continuation words just after a
semicolon. Comma-plus-conjunction, code comments, indentation following
statement endings, and end-of-text also receive negative predictions.
Semicolon responses are stronger near a document's start. A fading
boundary pressure carries across whitespace; it resets with the document.
The small, token-specific background variation is left at roughly zero.
"""
READS = ()

COORDINATORS = {'and', 'or', 'but', 'yet', 'else', 'pero', 'mais', 'aber'}
TRANSITIONS = {
    'however', 'therefore', 'thus', 'hence', 'so', 'otherwise',
    'instead', 'rather', 'sondern', 'doch', 'moreover',
    'consequently', 'nevertheless', 'although', 'ainsi',
}
# Function words and short words introducing a reference or explanation.
LINKING_WORDS = {
    'the', 'that', 'this', 'for', 'in', 'as', 'if', 'while', 'when',
    'which', 'such', 'also', 'then', 'though', 'whereas', 'what',
    'see', 'refs', 'etc', 'indeed', 'with', 'from', 'of', 'et', 'e', 'que',
    'assert', 'at', 'where', 'now', 'there', 'Fig',
}
FOREIGN_JOINERS = {'y', 'ed', 'und', 'и', 'و', 'denn'}
CODE_CONTROL = {'set', 'get', 'return', 'break', 'continue', 'throw'}
PRONOUNS = {'it', 'he', 'she', 'they', 'we', 'you', 'I'}
COMMA_JOIN = {
    'and': -0.76, 'or': -0.70, 'et': -0.46, 'und': -0.54,
    'и': -0.51, 'y': -0.28, 'e': -0.20,
}


def after_semicolon(s):
    word = s.strip()
    if word.lower() in COORDINATORS:
        return -4.5
    if word in TRANSITIONS:
        return -3.9
    if word in FOREIGN_JOINERS:
        return -2.8
    if word in CODE_CONTROL:
        return -2.0
    if word in LINKING_WORDS:
        return -2.8
    if word.isalpha() and not s.startswith(' '):
        return -0.6
    if word in PRONOUNS or word in {'a', 'an', 'nor'}:
        return -1.8
    if s.isspace():
        if '\n' in s or '\r' in s:
            return -2.2
        return -2.8
    if s == '\\' or word in {'(', '@', '"', "'"}:
        return -3.1
    if word == '#' and not s.startswith(' '):
        return -0.1
    if word.startswith(('//', '/*', '#', '`')):
        return -0.8 if '\n' in s else -2.7
    if word.startswith('}'):
        return -0.9
    if len(word) == 1 or word.isdecimal():
        return -1.4
    return -1.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, pressure, position = '', 0.0, 0
    else:
        _, previous, pressure, old_position = carry
        position = old_position + 1
    tail = previous.rstrip()
    newline = '\n' in previous or '\r' in previous
    word = s.strip()
    value = 0.0
    next_pressure = 0.0

    if s == '<|endoftext|>':
        value = -1.88
    elif tail.endswith(('；', '؛')):
        value = -1.5
        if word in {'而', '同时', '及', '或', 'و'} or s.isspace():
            value = -2.6
    elif tail.endswith(';'):
        if newline:
            next_pressure = 0.8 if previous.count('\n') > 1 else 1.1
            if len(s) <= 2 and '\t' not in s:
                next_pressure *= 0.8
            if s.isspace():
                value = -next_pressure
            elif word.startswith(('//', '/*', '#', '`')):
                value = -0.7 * next_pressure
        else:
            value = after_semicolon(s)
            value *= 1.0 + 0.8 / max(position, 1) ** 0.5
            if s == '\\' and tail.endswith("';"):
                value *= 1.4
            next_pressure = 2.5 if s.isspace() and '\n' not in s else 1.1
    elif tail.endswith(',') and s.startswith(' '):
        value = COMMA_JOIN.get(word, 0.02)
        next_pressure = max(0.0, -value) * 0.3
    # Whitespace keeps a weakened trace of the boundary.
    elif s.isspace() and (s.strip('\r\n') != ''):
        if newline:
            if tail.endswith('}'):
                next_pressure = 0.45
            elif tail.endswith('{'):
                next_pressure = 0.13
            elif previous.isspace():
                next_pressure = pressure * 0.5
                value = 0.08 if not next_pressure else 0.0
        elif pressure:
            next_pressure = pressure * (0.8 if '\t' in s else 0.5)
        value -= next_pressure
    elif previous.isspace() and pressure:
        if word.isdecimal():
            value = -0.45 * pressure
        elif word in COORDINATORS or word in TRANSITIONS:
            value = -0.8 * pressure
        elif word in LINKING_WORDS:
            value = -0.32 * pressure
        elif word.startswith(('//', '/*', '#')):
            value = -0.55 - 0.4 * pressure
        elif word.startswith('}') or word == 'return':
            value = -0.08 * pressure
        else:
            value = -0.22 * pressure
    elif word.startswith(('//', '/*', '#')):
        if word.startswith(('///', '/**', '##')):
            value = 0.0
        elif s.startswith(' '):
            value = -0.65 if word.startswith('//') else -0.30
        elif previous.isspace():
            value = -0.30
        else:
            value = -0.25

    return (doc, s, next_pressure, position), float(value)

programs.haiku:
"""Draft 9: what starts a new clause or statement right after a semicolon: a connective
('and', 'but', 'or', 'however', 'else') hits hardest, then determiners and prepositions, then
other lowercase words; capitalised names barely react. Also list 'and'/'or' after a comma,
comment markers, and the end-of-document token."""
READS = ()

CONNECTIVES = {"and", "but", "or", "however", "else", "hence", "yet", "therefore", "nor",
               "mais", "pero", "sondern"}
FUNCTION_WORDS = {"the", "in", "for", "this", "that", "if", "then", "of", "to", "with",
                  "on", "at", "from", "by", "as", "these", "those"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    last_sig = carry or ""
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        last_sig, prev = "", ""
    word = tok.strip()
    if tok == "<|endoftext|>":
        value = -1.9
    elif prev.endswith(";"):
        if word.lower() in CONNECTIVES:
            value = -4.8
        elif word == "":
            value = -2.2 if "\n" in tok else -3.0
        elif word.lower() in FUNCTION_WORDS:
            value = -2.9
        elif word[0].islower():
            value = -1.6
        elif word[0].isupper():
            value = -0.6
        else:
            value = -2.4
    elif word == "" and "\n" not in tok and last_sig == ";":
        value = -1.0   # indentation at the start of a line that follows a semicolon
    elif word in ("and", "or") and prev.endswith(","):
        value = -0.7   # list-joining 'and' / 'or'
    elif word in ("//", "#"):
        value = -0.7   # comment marker
    else:
        value = 0.0
    if word:
        last_sig = word[-1]
    return last_sig, value

programs.sol:
"""Approximate a colon/label feature from visible tokens.

Bare colons are negative, more so after digits and repeated delimiters.
Literal metadata headings and fused colon tokens have weaker or sometimes
positive responses. Document-initial 'Title:' is an exceptional large
negative/positive pair. Short naming phrases also give negative responses.

Only document-local position, the previous token, and a colon count are
remembered. Small background activations on other tokens are omitted.
"""
READS: tuple[str, ...] = ()

FIELD_NAMES = {
    'Name', 'Title', 'Date', 'Category', 'Author', 'Location', 'Tags',
    'Keywords', 'Posts',
}
OTHER_HEADINGS = {'Answer', 'Source', 'Description', 'Subject', 'From'}
NAMING_WORDS = {'word', 'words', 'term', 'terms', 'title', 'label', 'labels'}
COLON_PREFIXES = {')', '()', ']', '}', '.', '_', '`', '?'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, colon_count = 0, '', 0
    else:
        _, position, previous, colon_count = carry
    token = prefix.token_strings[-1]
    word = previous.strip()

    if position == 0 and token == 'Title':
        value = -7.886
    elif token == ':':
        if position == 1 and previous == 'Title':
            value = 8.644
        elif position == 0:
            value = -1.575
        elif word == 'Joined':
            value = 0.29
        elif previous == 'title':
            value = 0.65
        elif word in FIELD_NAMES or word == 'name':
            value = -0.50
        elif word in OTHER_HEADINGS:
            value = -0.70
        elif previous == 'Question':
            value = -0.33
        else:
            value = -1.027 - 0.014 * min(colon_count, 10)
            if word.isdigit():
                value -= 0.19
    elif token == '：':
        value = -0.55
    elif token.endswith(':') and token[:-1].isspace():
        value = -0.52
    elif token.endswith(':') and token[:-1] in COLON_PREFIXES:
        value = -0.44
    elif token == "':":
        value = -0.14
    elif token.rstrip('\r\n') == ':' and token.endswith('\n'):
        value = -0.13 if token.count('\n') == 1 else 0.0
    elif token.rstrip('\r\n') == '：' and token.endswith('\n'):
        value = 0.20
    elif token in {' of', ' for'} and word.lower() in {'name', 'names'}:
        value = -1.25 if word.lower() == 'name' else -0.90
    elif token == ' for' and word.lower() in NAMING_WORDS:
        value = -0.75
    else:
        value = 0.0

    colon_count += token == ':'
    return (document, position + 1, token, colon_count), value

programs.luna:
"""Treat colon punctuation as a strong delimiter; numeric labels get a stronger signal."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if token == ":":
        # A fresh document headed by "Title:" is a distinct, strong header cue.
        if (len(prefix) >= 3
                and prefix.token_strings[-2].strip() == "Title"
                and prefix.document_ids[-2] != prefix.document_ids[-3]):
            return None, 8.64
        before = prefix.token_strings[-2].rstrip() if len(prefix) >= 2 else ""
        if before and before[-1].isdigit():
            return None, -1.27
        return None, -1.05

    if token.startswith(":") and token[1:] and not token[1:].strip("\n\r\t "):
        newlines = token[1:].count("\n")
        return None, -0.16 if newlines == 1 else 0.03
    if token.strip() == ":":
        return None, -0.54
    if token == "：":
        return None, -0.53
    if token in {"):", "]:", "}:",
    }:
        return None, -0.49
    return None, 0.0

programs.sol:
"""Detect vertical-bar punctuation, not the bars in message markers.
Single bars respond strongly; repeated bars nearby suppress the response.
Doubled bars, line endings, and assignment operators are weaker. Numeric
and dashed cells weaken it; line starts and early document positions give
a small boost. State resets for each document. Unicode vertical lines and
TeX bar commands get form-specific values; everything else is zero.
"""
READS = ()

UNICODE_BARS = {'│': 0.40, '｜': 0.60, '∣': 0.22, '‖': 0.14}
TEX_BARS = {
    '\\lvert': 1.30, '\\rvert': 0.85, '\\vert': 1.10,
    '\\lVert': 0.80, '\\rVert': 0.45, '\\Vert': 0.60,
    '\\mid': 0.53,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position = 0.0, '', 0
    else:
        recent, previous, position = carry[1] * 0.92, carry[2], carry[3] + 1
    token = prefix.token_strings[-1]
    density = recent / (1.0 + recent)
    value, count = 0.0, 0.0
    special = token.startswith('<|') and token.endswith('|>')
    if '|' in token and not special:
        spaced = token.startswith(' ')
        if '||' in token:
            value = (0.19 if spaced else 0.08) - 0.34 * density
            count = 0.5
        else:
            if '\n' in token:
                if token.count('\n') > 1:
                    base = 0.61
                else:
                    base = 0.89 if spaced else 0.68
            elif token in ('|', ' |'):
                base = 1.35 if spaced else 1.11
            elif '=' in token:
                base = 0.54
            elif token.strip() in ('|.', '|$', '|,', '|;', '|--'):
                base = 0.46
            else:
                base = 1.20
            value = base - 0.91 * density
            value -= 0.16 * previous.strip().isdigit()
            value += 0.10 * previous.endswith('\n') + 0.08 * (position < 32)
            if len(previous) > 2 and set(previous.strip()) == {'-'}:
                value -= 0.20
            count = 1.0
    elif token.strip() in UNICODE_BARS:
        value = UNICODE_BARS[token.strip()]
    elif token in ('vert', 'Vert', 'mid'):
        for command, base in TEX_BARS.items():
            if (previous + token).endswith(command):
                value, count = base - 0.25 * density, 0.5
                break
    return (doc, recent + count, token, position), float(value)

programs.luna:
"""Use vertical-bar punctuation as a weak cue, slightly stronger when space-prefixed."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "|" not in token:
        return None, 0.0
    if token.startswith(" "):
        return None, 0.35
    if token.endswith("\n"):
        return None, 0.24
    return None, 0.26

programs.haiku:
"""Layer-0 MLP down-projection component 5879: a lexical detector, mostly about "covering".

Strongest, negative: the role word "assistant" directly after the chat token "<|im_start|>",
which opens an assistant turn. Its activation there is about -0.94. The same word in
ordinary prose (with a leading space) is about -0.35.

Strongest, positive: the word "cover" and its forms (cover, covers, covered, covering,
coverage), about +1.2. The Chinese and Japanese words for cover (覆盖, 蓋, 覆, 全覆盖, 冠)
are about +1 to +3. Words for something placed on top (lid, roof, canopy, overlay, 屋顶,
帽) are about +0.5 to +1. Seal and stamp (seal, stamp, 印, 章) are about +0.5 to +0.8, and
Chinese words containing 加 ("add") about +0.6. PHP file names are a little negative, about
-0.35. Every other token predicts 0.

This is only the part of the component that a short list of words can name. Most of its
variance is a diffuse tail of small values on ordinary tokens, which this program leaves at 0.
"""

READS = ()

# The role word that opens an assistant turn.
ASSISTANT_TURN = -0.94  # "assistant" directly after "<|im_start|>"
ASSISTANT_PROSE = -0.35  # " assistant" elsewhere

# Words for covering, with the leading space stripped and lowercased.
COVER_WORDS = {"cover", "covers", "covered", "covering", "coverage", "_cover", "-covered"}
COVER_VALUE = 1.2
COVER_CHARS = {"覆盖": 2.0, "全覆盖": 1.5, "蓋": 3.0, "覆": 1.1, "冠": 1.2}

# Things placed on top: lid, roof, canopy, overlay, and the Chinese roof and cap.
TOP_WORDS = {"lid", "roof", "canopy", "overlay", "rooftop"}
TOP_CHARS = {"屋顶": 0.8, "帽": 0.7}

# Seal and stamp, and the Chinese seal characters.
SEAL_WORDS = {"stamp", "stamps", "seal", "seals", "sealed"}
SEAL_CHARS = {"印": 0.8, "章": 0.7}

# Chinese words containing 加 ("add", "plus").
ADD_VALUE = 0.6

PHP_WORDS = {"php", ".php"}
PHP_VALUE = -0.35


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    # The previous token, unless a new document starts here.
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]

    if token == "assistant" and previous == "<|im_start|>":
        value = ASSISTANT_TURN
    elif token == " assistant":
        value = ASSISTANT_PROSE
    elif word in COVER_WORDS:
        value = COVER_VALUE
    elif token in COVER_CHARS:
        value = COVER_CHARS[token]
    elif word in TOP_WORDS:
        value = 0.5
    elif token in TOP_CHARS:
        value = TOP_CHARS[token]
    elif word in SEAL_WORDS:
        value = 0.5
    elif token in SEAL_CHARS:
        value = SEAL_CHARS[token]
    elif "加" in token:
        value = ADD_VALUE
    elif word in PHP_WORDS:
        value = PHP_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a local numeral-transition feature seen in the training data.

Digits following 6 give large negative values, except another 6. The
responses are weaker after 8 and 4, and usually positive after 3. The
pairs 16 and 26 give small negative and positive values. A document-
initial 6 strengthens the following digit's response. Fullwidth digits
are treated as their ASCII equivalents.

A single separator attenuates the digit response. ASCII letter-only
fragments immediately after 6 give a modest negative value (smaller for
ordinal suffixes). All other cases predict zero. State resets between
documents. Fine lexical effects and longer-range context are omitted.
"""
READS = ()

# Each row is indexed by the new decimal digit, 0 through 9.
DIGIT_PAIRS = {
    '6': (-1.39, -2.70, -1.97, -2.76, -2.86,
          -3.00, 0.06, -2.22, -1.81, -2.19),
    '8': (-0.17, -0.65, -0.45, -0.69, -0.66,
          -0.70, 0.15, -0.36, -0.22, -0.26),
    '4': (-0.02, -0.35, -0.23, -0.35, -0.36,
          -0.38, 0.13, -0.10, 0.01, 0.04),
    '3': (0.09, 0.15, 0.15, 0.24, 0.27,
          0.19, 0.00, 0.18, 0.16, 0.16),
}
SEPARATORS = {' ': 0.25, '.': 0.15, ',': 0.08,
              '-': 0.03, '/': 0.05, '\n': 0.08}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    if len(token) == 1 and "０" <= token <= "９":
        token = str(ord(token) - ord("０"))
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        if previous in DIGIT_PAIRS:
            value = DIGIT_PAIRS[previous][digit]
            if previous == '6' and before_previous == '':
                value *= 1.45
        elif token == '6' and previous == '1':
            value = -0.16
        elif token == '6' and previous == '2':
            value = 0.22
        elif previous in SEPARATORS and before_previous in DIGIT_PAIRS:
            value = SEPARATORS[previous] * DIGIT_PAIRS[before_previous][digit]
    elif previous == '6' and token.isascii() and token.isalpha():
        value = -0.3 if token in {'st', 'nd', 'rd', 'th'} else -0.55
    return (doc, token, previous), float(value)

"""A joint-word detector with spelling fragments and local phrase continuation.

'Joint' fires in both the physical-connection and shared-action senses.
Inflections and fragments usually fire less; document starts fire more.
Bone, seam, boundary, and East Asian joint/union words have smaller responses.
Some activation continues into a following suffix or phrases such as
'joint venture' and 'joints of'. This is a lexical approximation,
not a disambiguator: most other tokens are predicted nearly silent.
"""
READS = ()

BOUNDARY_WORDS = {'border', 'borders', 'contour', 'contours', 'jurisdiction'}
BONE_INJURIES = {'arthritis', 'fracture', 'fractures'}
SUFFIX_RESPONSE = {'ed': 4.2, 'ing': 3.6, 'ly': 3.3, 'ness': 1.9, 'er': 1.5}
JOINT_PHRASE_NOUNS = {
    'venture', 'ventures', 'probability', 'density', 'distribution',
    'angle', 'angles', 'gap', 'research', 'service', 'services',
    'commission', 'chiefs', 'base', 'center', 'replacement', 'pain',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    previous_joint = carry[2] if same_document else False
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()

    if word == 'joint':
        if token == ' joint':
            value = 7.0
        elif token == ' Joint':
            value = 6.5
        elif token == 'Joint':
            value = 7.5
        elif prev.endswith('dis'):
            value = 2.9
        elif prev.endswith('ad'):
            value = 4.0
        else:
            value = 6.0
    elif word == '_joint':
        value = 4.5
    elif word == 'joints':
        value = 6.0
    elif word == 'jointly':
        value = 3.8
    elif word == 'disjoint':
        value = 1.7
    elif word in {'oint', 'oints'}:
        if prev.endswith(('adj', 'conj')):
            value = 3.75
        elif prev.endswith('j'):
            value = 6.4
        else:
            value = 2.4
    elif token == 'INT':
        value = 4.8 if prev.endswith('jo') else 0.28
    elif word in {'nt', 'nts'}:
        value = 0.25 if token.islower() else 0.15
    elif word in {'关节', '關節', '関節'}:
        value = 2.3 if previous == '肩' else 4.0
        if not same_document:
            value = 5.1
    elif word in {'联合', '聯合'}:
        value = 1.25
    elif word in {'bone', 'bones'}:
        value = 1.0 if word == 'bones' else 0.65
        if token == word:
            value = 0.28
    elif word.startswith('骨'):
        value = 0.55
    elif word in {'节', '節'}:
        value = 1.6 if previous in {'關', '関'} else 0.7
    elif word in {'boundary', 'boundaries'}:
        value = 0.6 if word == 'boundary' else 0.4
    elif word in {'seam', 'seams', 'seamless', 'seamlessly'}:
        value = 0.45 if word.startswith('seamless') else 0.75
    elif word in BOUNDARY_WORDS or word in BONE_INJURIES:
        value = 0.3
    else:
        value = -0.002

    # Whole words and completed j + oint fragments share continuation rules.
    current_joint = word in {'joint', 'joints', 'oint', 'oints'} and value >= 5.0
    if not same_document and word == 'joint':
        value = 10.4 if token == 'Joint' else 10.0

    if previous_joint:
        if word in SUFFIX_RESPONSE:
            value = SUFFIX_RESPONSE[word]
        elif word in {'of', 'between'}:
            value = 1.8
        elif word.lstrip('_') in JOINT_PHRASE_NOUNS:
            value += 0.7
    elif prev == 'oint' and word == 'ing':
        value = 1.1
    elif prev in {'bone', 'bones', 'boundary', 'boundaries'} and word == 'of':
        value = 0.3

    return (doc, token, current_joint), float(value)

