programs.sol:
"""A signal for digit continuations after '1', and for movement/proximity words.

The digit response grows roughly logarithmically with its numeric value
when it follows token '1' (more weakly across a decimal point). Direction
toward something and comparative nearness give negative responses. 'After' continuations, especially 'after all', give
positive responses. A few 'other/another' phrases are positive as well.
Unmatched tokens receive zero; small token-specific effects are omitted.
"""
from math import log

READS = ()

NEARNESS = {
    'toward': -3.88,
    'towards': -3.83,
    'closer': -2.28,
    'closest': -1.24,
    'nearest': -1.41,
    'near': -0.57,
    'tow': -2.28,  # The 'Tow' fragment also occurs in towels.
}


PROXIMITY_TO = {
    'close': -0.75, 'closer': -2.16,
    'closest': -1.59, 'nearest': -1.07,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is not None and carry[0] == doc:
        previous, penultimate = carry[1:]
    else:
        previous = penultimate = ''
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        strength = -0.05 if digit < 2 else 0.80 * log(digit) - 0.39
        if previous == '1':
            value = strength
        elif penultimate == '1' and previous == '.':
            value = 0.28 * strength
    else:
        word = token.strip().lower()
        before = previous.strip().lower()
        value = NEARNESS.get(word, 0.0)
        if before in {'t', 'tow'}:
            value = NEARNESS.get(before + word, value)
        if before == 'after':
            if word == 'all':
                value = 4.23
            elif word == 'being':
                value = 2.27
            elif word in {'the', 'a', 'an', 'his', 'her', 'this', 'its'}:
                value = 0.20
            elif word in {'each', 'every', 'some', 'several', 'much',
                          'both', 'any', 'many'}:
                value = 1.24
            elif word.isalpha():
                value = 0.26 if word.endswith('ing') else 0.41
        elif word == 'to' and before in PROXIMITY_TO:
            value = PROXIMITY_TO[before]
        elif word == 'the' and before in {'toward', 'towards', 'near'}:
            value = -0.80
        elif before in {'other', 'another'}:
            if word == 'hand':
                value = 0.84
            elif word == 'way':
                value = 0.60
            elif word == 'half':
                value = 1.06
    return (doc, token, previous), float(value)

programs.luna:
"""Estimate a number's second digit response, with a few contextual word
responses: comparative closeness, direction, and two common word contexts.
"""
READS = ()

DIGIT_RESPONSE = {2: 0.15, 3: 0.50, 4: 0.73, 5: 0.90,
                  6: 1.05, 7: 1.15, 8: 1.24, 9: 1.38}


def step(carry, prefix, upstream):
    i = prefix.position
    current = prefix.token_strings[i].strip()
    same_doc = i > 0 and prefix.document_ids[i] == prefix.document_ids[i - 1]
    previous = prefix.token_strings[i - 1].strip().lower() if same_doc else ""

    if len(current) == 1 and current in "0123456789":
        if previous.endswith("1"):
            return None, float(DIGIT_RESPONSE.get(int(current), 0.0))
        return None, 0.0

    word = current.lower()
    if word == "closer" and previous in {"is", "are"}:
        return None, -2.1
    if word == "closest" and previous == "the":
        return None, -1.0
    if word == "to" and previous == "closer":
        return None, -2.1
    if word == "towards":
        return None, -3.2
    if word == "the" and previous == "towards":
        return None, -0.8
    if word == "being" and previous == "after":
        return None, 1.2
    if word == "aspect" and previous == "another":
        return None, 0.45
    return None, 0.0

programs.sol:
"""A selective lexical detector of negation, exclusion and partial quantities.

The separate marker 'non' and Chinese/Japanese 非 get large positive values.
Other listed markers get smaller values; unlisted tokens get zero. This is
not a detector of the scope of negation. Grammatical context distinguishes
'not' after do/be from 'not' after modal or perfect auxiliaries, including
split contractions. A decaying count of English versus Romance function
words lowers 'non' in Romance text and distinguishes the prefix 'un-' from
the article 'un'. Case, token boundaries and code punctuation also matter.
All remembered context resets at each document boundary.
"""
READS = ()

ENGLISH = set('''the and of to is with that it this are be or from by an
    not have was which you we will can for does do did were has would
    should could their they its as but'''.split())
ROMANCE = set('''di che il gli una uno della delle degli dello sono anche
    più ma nel nella questo questa per è si
    de le les des une du est dans avec pour et pas que la
    el los las del por para es pero con se'''.split())
MODALS = set('can could may might must shall should will would need dare'.split())
PERFECT = {'have', 'has', 'had'}
DO = {'do', 'does', 'did'}
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'being', 'been'}
NEGATORS = {'не', 'nicht', 'não', 'niet', 'tidak', '不', '不是', '并不'}
WITHOUT = {'sans', 'без', 'ohne', 'sem', 'không'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, language = '', 0.0
    else:
        _, previous, language = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    bare = word.lstrip('._/-(')

    if bare == 'non':
        punctuated = word != bare
        value = 3.9 if language < 0.0 and not punctuated else 7.6
        if punctuated:
            value = 7.3
        elif not raw[:1].isspace():
            value -= 0.8
        if raw.strip() == 'NON':
            value -= 1.4
        if previous.endswith('\\'):
            value = 3.8  # e.g. the LaTeX command \\nonumber
        if previous == 'dé' and not raw[:1].isspace():
            value = 2.1  # a continuation inside a French word
    elif word == '非':
        value = 6.2
    elif word == '비':
        value = 2.2 if raw[:1].isspace() else 1.2
    elif word == '是非':
        value = 8.0
    elif bare == 'not':
        if previous in MODALS:
            value = 0.04
        elif previous in PERFECT:
            value = 0.12
        elif previous in DO:
            value = 0.72
        elif previous == 'am':
            value = 0.92
        elif previous in BE:
            value = 0.66
        elif previous in {'why', 'ought'}:
            value = 0.25
        elif previous == 'or':
            value = 0.5
        else:
            value = 0.94
        if raw.strip().isupper():
            value = 0.95
        elif raw.strip()[:1].isupper():
            value = 1.2
        elif not raw.startswith(' '):
            value += 0.2
    elif word in {"'t", '’t'}:
        if previous in {'don'}:
            value = 0.91
        elif previous in {'doesn', 'didn'}:
            value = 0.71
        elif previous in {'isn', 'aren', 'wasn', 'weren', 'ain'}:
            value = 0.53
        else:
            value = 0.08
    elif bare == 'un':
        if raw.strip().isupper():
            value = 0.1  # usually the United Nations, not negation
        elif word != bare or raw.strip()[:1].isupper():
            value = 0.9
        elif not raw[:1].isspace():
            value = 0.2  # often just a word-internal syllable
        else:
            value = -0.15 if language < 0.0 else 1.05
    elif word == 'than':
        if previous in {'less', 'rather'}:
            value = 0.6
        elif previous in {'other', 'greater', 'fewer'}:
            value = 0.76
        else:
            value = 1.03
    elif bare == 'without':
        value = 1.09
    elif bare in NEGATORS:
        value = 0.8
        if bare == 'nicht':
            value = 2.95 if raw.strip()[:1].isupper() else 0.96
    elif word in {'而不', '毫不', '而不是', '并非'}:
        value = 1.5
    elif word == '而非':
        value = 3.85
    elif word == 'غير':
        value = 1.9
    elif bare in {'nonlinear', 'nonzero', 'nonnull', 'nonprofit'}:
        value = 1.5
    elif bare in WITHOUT:
        value = 0.58
    elif bare in {'either', 'almost', 'half'} or word == '半':
        value = 0.8
    elif word == 'neither':
        value = 0.5
    elif word == 'beyond':
        value = 0.96
    elif word in {'!=', '≠'}:
        value = 0.6
    elif word == '!==':
        value = 0.92
    else:
        value = 0.0

    language = 0.97 * language + (word in ENGLISH) - (word in ROMANCE)
    return (doc, word, language), float(value)

