"""Mark common negation morphemes and explicit comparison markers."""
READS = ()

NEGATORS = {"not", "without", "un", "n't", "'t", "’t", "并不", "비"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    if token == "non":
        return None, 7.2
    if token in {"'t", "’t"}:
        previous = prefix.token_strings[-2].casefold() if len(prefix) > 1 else ""
        if not previous.endswith("n"):
            return None, 0.0
