        return None, 0.9
    if token == "than":
        return None, 0.7
    if token == "!=":
        return None, 0.55
    return None, 0.0

programs.sol:
"""Spelling detector, principally m away from the start of a word.

Noninitial Latin m has a stronger response in short tokens and beside
certain preceding letters. Word-initial m is usually weak. Analogous m
letters in other scripts, chat boundaries, and repeated punctuation have
separate modest responses. This is a lexical approximation, not a topic
classifier; it captures broad spelling rather than word-specific exceptions.
"""
import math

READS = ()

# Familiar letter pairs ending in m, not a vocabulary lookup table.
BEFORE_M = {'a': 0.55, 'e': 0.41, 'i': 0.22, 'o': 0.43,
            'u': 0.15, 'r': 0.53, 'm': 0.59}
CHAT = {'<|im_end|>': 2.31, '<|im_start|>': 0.40,
        '<think>': 0.88, '</think>': 0.77}
M_LETTERS = frozenset('मমਮમମமమಮമมມመ')
M_KANA = frozenset('まみむめもマミムメモ')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.startswith('<') and token.endswith('>'):
        return None, CHAT.get(token, 0.014)
    text = token.lower()
    word = text.strip()
    leading_space = token[:1].isspace()
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    after_letter = same_doc and prefix.token_strings[-2][-1:].isalpha()
    value = 0.014
    if 'm' in text:
        initial = word.startswith('m') and (leading_space or not after_letter)
        if word == 'm':
            value += (1.5 if after_letter and not leading_space else 0.7)
        elif initial and len(word) == 2 and word.count('m') == 1:
            value += 0.25
        elif not initial or 'm' in word[1:]:
            value += 0.73 - 0.19 * math.log(max(len(word), 1))
            value += 0.15 * (len(word) <= 3)
            value += 0.18 * word.endswith('m')
            value += 0.31 * word.endswith('ms')
            value -= 0.20 * (text.count('m') > 1)
            for letter, strength in BEFORE_M.items():
                value += strength * (letter + 'm' in text)
    if 'м' in text:
        value += 0.86 - 0.69 * (leading_space and word.startswith('м'))
    if 'μ' in text:
        value += 0.6 if leading_space else 1.5
    if 'µ' in text:
        value += 0.3
    if 'م' in text:
        value += 0.78
    if any(c in M_LETTERS for c in text):
        value += 0.84
    if any(c in M_KANA for c in text):
        value += 0.42
    # Hangul syllables with initial mieum or final mieum (the m consonant).
    if any('\uac00' <= c <= '\ud7a3' and
           ((ord(c) - 0xac00) // 588 == 6 or
            (ord(c) - 0xac00) % 28 == 16) for c in text):
        value += 0.41
    if any('\u4e00' <= c <= '\u9fff' for c in text):
        value += 0.08
    if '\ufffd' in text:
        value += 0.11
    if any(c * 2 in text for c in "`'\""):
        value += 0.39
    if '===' in text:
        value += 0.60
    if '---' in text:
        value += 0.22
    if '...' in text or '…' in text:
        value += 0.18
    if '/**' in text or '///' in text:
        value += 0.58
    return None, float(value)

programs.luna:
"""An m-in-token cue, with small rules for chat and thinking markers."""
READS = ()

M_CHARS = frozenset("mMмМ")
CHAT_BOUNDARIES = {"<|im_end|>": 2.35, "<|im_start|>": 0.45}
THINK_TAGS = frozenset(("<think>", "</think>"))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHAT_BOUNDARIES:
        return None, CHAT_BOUNDARIES[token]
    if token in THINK_TAGS:
        return None, 0.90

    text = token.strip()
    if not any(char in M_CHARS for char in text):
        return None, 0.0
    if text.endswith(tuple(M_CHARS)):
        return None, 1.05
    if text.startswith(tuple(M_CHARS)):
        return None, 0.08
    return None, 1.0

programs.sol:
"""Short Latin consonant clusters, with a particularly strong negative h signal.

Recognize h followed by another consonant, optionally preceded by a vowel,
c, or vowel+c. German-looking ch clusters and isolated consonant fragments
count; ordinary longer English th/sh/gh/wh words do not. Extra letters and
word-start spaces attenuate the response. The continuation o+hl is weaker.
A leading slash, hyphen or underscore reduces the response; PHP also counts
as a consonant-heavy acronym. This omits the component's weak lexical effects.
"""

READS = ()
VOWELS = 'aeiouäöü'
CONSONANTS = 'bcdfgjklmnpqrstvwxz'
OTHER_STRENGTH = {
    'j': .58,
    'z': .89,
    'k': .38,
    'g': .34,
    'w': .21,
}


def strength_after_h(letter):
    if letter == 'l':
        return 3.02
    if letter == 'r':
        return 2.18
    if letter in 'dtm':
        return 2.01
    if letter in 'bfknpw':
        return 1.53
    if letter in 'cgjsvx':
        return 1.14
    return .59


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    boundary = 1.
    if raw.startswith(('/', '-', '_')):
        raw = raw[1:]
        boundary = .6
    word = raw.lower()
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].lower()
    if not word or not all(c.isalpha() and ord(c) < 600 for c in word):
        return None, 0.0
    response = 0.
    for i in range(len(word) - 1):
        first, second = word[i:i + 2]
        left, right = word[:i], word[i + 2:]
        if first == 'h' and second in CONSONANTS:
            if word.startswith(('http', 'hmm')):
                continue
            if left == '':
                scale = 1.
            elif (len(left) == 1 and left in VOWELS) or left == 'c':
                scale = .75
            elif len(left) == 2 and left[0] in VOWELS and left[1] == 'c':
                scale = .8 if left[0] in 'aä' else .5
            elif left == 'sc' or (left in ('s', 't', 'g', 'w') and not right):
                scale = .4
            else:
                continue
            if left in ('e', 'o', 'u'):
                scale *= .75
            if left in ('ä', 'ö', 'ü'):
                scale *= .5
            if left == 'c' and second == 't':
                scale = .9
            scale *= .6**len(right)
            if not left and len(right) == 1 and right in VOWELS:
                scale = 1.
            if word == 'hl' and previous.endswith('o') and not token.startswith(' '):
                scale *= .45
            response -= strength_after_h(second) * scale
        elif first in 'jzkgw' and second in CONSONANTS and first != second:
            if left not in ('', 'a', 'e', 'i', 'o', 'u'):
                continue
            if first == 'g' and second in 'lr':
                continue
            if first == 'k' and second in 'cn':
                continue
            if first == 'w' and second in 'rl':
                continue
            strength = OTHER_STRENGTH[first]
            if second not in 'bcdgkpt':
                strength *= .65
            response -= strength * .6**(len(word) - 2)
    if word == 'php':
        response -= .72
    if token.startswith(' '):
        response *= .8
    return None, float(boundary * response)

"""Detect nasal-consonant spellings in short Latin-letter tokens.

A token consisting of m/n followed by a consonant gives a negative response,
especially mp. Capitalisation, a new-word space, and an immediately preceding
vowel adjust its strength. Longer pieces beginning with these clusters are
weaker. The Python alias `as np` is a particularly strong np context.
These spelling rules approximate the large responses, not every small effect.
"""
import unicodedata

READS = ()
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxyz')
# Lower-case and all-capital magnitudes for nasal consonant pairs.
CLUSTERS = {
    'mp': (-2.05, -2.86),
    'mb': (-1.16, -1.22),
    'nd': (-1.21, -1.48),
    'nt': (-0.90, -1.17),
    'nc': (-0.94, -1.21),
    'np': (-0.87, -0.67),
    'ns': (-0.82, -1.09),
    'ng': (-0.67, -0.94),
    'nf': (-0.68, -0.95),
    'nh': (-0.36, -0.63),
}

def response(s, previous):
    core = s.strip(' ._-/\\=(:')
    lower = core.lower()
    size = len(lower)
    if size == 2 and lower[0] in 'mn' and lower[1] in CONSONANTS:
        if lower in CLUSTERS:
            value = CLUSTERS[lower][int(core.isupper())]
        elif lower[1] in 'mnlrwy':
            value = -0.07
        else:
            value = -0.23 if lower[0] == 'm' else -0.33
            if core.isupper():
                value -= 0.07 if lower[0] == 'm' else 0.27
        if s.startswith(' '):
            if lower == 'mp':
                value += 0.21
            elif lower == 'np':
                value -= 0.17
            elif lower[0] == 'n':
                value -= 0.12
        elif s[0].isalpha() and previous:
            c = previous[-1].lower()
            vowel = unicodedata.normalize('NFD', c)[0] in 'aeiou'
            if vowel:
                value += 0.45 if lower == 'mp' else (
                    0.38 if lower[0] == 'n' else 0.08)
        if lower == 'np' and previous.strip() == 'as':
            value -= 0.64
        return value
    if size > 2 and lower[:2] in CLUSTERS:
        pair = lower[:2]
        return -0.98 if pair == 'mp' else (
            -0.50 if pair in {'nd', 'ns'} else -0.16)
    if size == 3 and lower[-2:] in CLUSTERS:
        if all(c in CONSONANTS for c in lower):
            return -0.34
        if lower[-2:] in {'mp', 'mb'}:
            return -0.16
    return 0.002

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), float(response(s, previous))
